//! **The window thread's waits are one registry, and the code and the document agree with it**
//! (design note 2026-09-26, §9.1's first row and revision (c)8 item 9; budget note R7).
//!
//! `window_waits.tsv` is the registry. Its `# doors` section is held equal to
//! `bt_platform::admission::doors` by reading each type's own constants — through `KEY`, which the
//! `door!` macro builds from the same tokens as the type — never their text. Its `# rows` section
//! *is* `docs/ARCHITECTURE.md` §5.3: the table there is rendered from it, and
//! `scripts/dev/generate-window-waits-table.ps1` writes it back when they differ.
//!
//! A child of `hang_watch` because the stations are `hang_watch`'s: a door's station byte is read
//! back through `Station::from_byte`, which only this module may call.
//!
//! **And the source guard's prohibitions** (A1e): `every_door_is_where_the_registry_says` reads the
//! product's source through `bt_source` and holds the escapes the compiler cannot see — the unsafe
//! fences, the one capability constructor, the pinned role and phase writers, the lint
//! suppressions, the constructs a lint cannot see through and their owners (`# owners`), the
//! synchronous doors, and the closed `Drop` inventory — each as a named assertion.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::path::PathBuf;

use bt_platform::admission::{DoorKey, Phase, doors};
use bt_source::call_graph::{Arms, CallGraph, Edge, ItemId, Resolver, Target, Unresolved};
use bt_source::{
    Certainty, FileRecord, ImplRecord, Index, ItemKind, ItemQuery, ItemRecord, MacroKind,
    Occurrence, ResolveCutoff, TargetKind, TraitId, TraitResolver,
};

use super::{STATION_COUNT, Station};

/// The registry, as the build has it.
const REGISTRY: &str = include_str!("window_waits.tsv");

/// Where the generated table begins and ends in `docs/ARCHITECTURE.md`.
const BEGIN: &str = "<!-- window_waits.tsv: generated by scripts/dev/generate-window-waits-table.ps1; edit the registry, not this table -->\n";
const END: &str = "<!-- window_waits.tsv: end -->";

/// Where the generated completions ledger begins and ends in `docs/ARCHITECTURE.md` (§5.5).
const COMPLETIONS_BEGIN: &str = "<!-- window_waits.tsv # completions: generated by scripts/dev/generate-window-waits-table.ps1; edit the registry, not this table -->\n";
const COMPLETIONS_END: &str = "<!-- window_waits.tsv # completions: end -->";

/// One section's lines, cut at the tabs, after checking its header is `columns`.
fn section(name: &str, columns: &[&str]) -> Vec<Vec<&'static str>> {
    section_in(REGISTRY, name, columns)
}

/// [`section`], of a registry's text.
fn section_in<'r>(registry: &'r str, name: &str, columns: &[&str]) -> Vec<Vec<&'r str>> {
    numbered_section_in(registry, name, columns)
        .into_iter()
        .map(|(_, cells)| cells)
        .collect()
}

/// [`section_in`], each line with its 1-based line number in `registry`.
fn numbered_section_in<'r>(
    registry: &'r str,
    name: &str,
    columns: &[&str],
) -> Vec<(usize, Vec<&'r str>)> {
    let marker = format!("# {name}");
    let mut lines = registry
        .lines()
        .enumerate()
        .skip_while(|(_, line)| *line != marker)
        .skip(1)
        .take_while(|(_, line)| !line.starts_with("# "))
        .filter(|(_, line)| !line.is_empty() && !line.starts_with("##"));
    let header: Vec<&str> = lines
        .next()
        .unwrap_or_else(|| panic!("the registry has a `{marker}` section with a header"))
        .1
        .split('\t')
        .collect();
    assert_eq!(header, columns, "`{marker}`'s columns");
    lines
        .map(|(at, line)| {
            let cells: Vec<&str> = line.split('\t').collect();
            assert_eq!(cells.len(), columns.len(), "`{marker}`: {line}");
            (at + 1, cells)
        })
        .collect()
}

const ROW_COLUMNS: [&str; 5] = ["row", "status", "call", "where", "disposition"];
const DOOR_COLUMNS: [&str; 7] = [
    "door",
    "row",
    "station",
    "phases",
    "call",
    "minted at",
    "measures",
];
const VOCABULARY_COLUMNS: [&str; 3] = ["path", "targets", "reason"];

/// The phases a registry cell names, in the order `Phase` declares them.
fn phases_named(cell: &str) -> Vec<Phase> {
    cell.split(", ")
        .map(|name| match name {
            "Starting" => Phase::Starting,
            "Running" => Phase::Running,
            "Exiting" => Phase::Exiting,
            other => panic!("`{other}` is not a phase"),
        })
        .collect()
}

fn phases_of(key: DoorKey) -> Vec<Phase> {
    [Phase::Starting, Phase::Running, Phase::Exiting]
        .into_iter()
        .filter(|phase| key.phases().contains(*phase))
        .collect()
}

/// RED (A1a, §9.1 row 1) — **every door type is a line of the registry, in its order, and says
/// what its line says: the row, the station and the phases.**
///
/// The registry is the list a reviewer reads and the types are what the compiler holds a door
/// to; a door added, dropped or renumbered on one side only would be a door the budget counts
/// under the wrong row, or a station the hang report prints for the wrong call. The station is
/// compared by the byte the meter enters and read back through `Station::from_byte`, so a byte
/// past the last station — which `from_byte` would quietly answer `starting` for — is red here
/// before any report could print it.
///
/// MUTATION: give `doors::PtyResize` station byte 5 (`Present`) in `bt_platform::admission` and
/// the station assertion goes red; add a door type without a line and the count does.
#[test]
fn every_door_type_is_a_registry_line_and_says_what_the_line_says() {
    let lines = section("doors", &DOOR_COLUMNS);
    let rows: Vec<&str> = section("rows", &ROW_COLUMNS)
        .into_iter()
        .map(|cells| cells[0])
        .collect();
    assert_eq!(
        doors::ALL.len(),
        lines.len(),
        "one door type per registry line"
    );
    for (key, line) in doors::ALL.iter().zip(&lines) {
        let name = key.name();
        assert_eq!(name, line[0], "the registry's order is the types' order");
        assert_eq!(key.row().label(), line[1], "{name}'s row");
        assert!(
            line[1] == "§5.2" || rows.contains(&line[1]),
            "{name} serves row {}, which the rows section does not have",
            line[1]
        );
        let byte = key.station();
        assert!(
            usize::from(byte) < STATION_COUNT,
            "{name}'s station byte {byte} is past the last station"
        );
        let station = Station::from_byte(byte);
        assert_eq!(
            station as u8, byte,
            "{name}'s station byte reads back as itself"
        );
        assert_eq!(format!("{station:?}"), line[2], "{name}'s station");
        assert_eq!(phases_of(*key), phases_named(line[3]), "{name}'s phases");
    }
}

/// RED (A1a) — **the registry's rows are numbered once each and carry a status it knows; its
/// vocabulary names each path once, for the targets there are.**
///
/// A status outside the four is a row whose state nobody can read off; a path listed twice is
/// one effect with two reasons.
///
/// MUTATION: write `status` `closed` on a row and it goes red.
#[test]
fn the_registrys_rows_and_vocabulary_are_well_formed() {
    let rows = section("rows", &ROW_COLUMNS);
    let mut numbers: Vec<&str> = rows.iter().map(|cells| cells[0]).collect();
    for cells in &rows {
        assert!(
            ["done", "open", "ruled to stay", "pending"].contains(&cells[1]),
            "row {} has status `{}`",
            cells[0],
            cells[1]
        );
    }
    let count = numbers.len();
    numbers.sort_unstable();
    numbers.dedup();
    assert_eq!(numbers.len(), count, "a row numbered twice");

    let vocabulary = section("vocabulary", &VOCABULARY_COLUMNS);
    let mut paths: Vec<&str> = vocabulary.iter().map(|cells| cells[0]).collect();
    for cells in &vocabulary {
        for target in cells[1].split(", ") {
            assert!(
                ["all", "windows", "macos"].contains(&target),
                "{} names target `{target}`",
                cells[0]
            );
        }
    }
    let count = paths.len();
    paths.sort_unstable();
    paths.dedup();
    assert_eq!(paths.len(), count, "a vocabulary path listed twice");
}

/// §5.3's table and the doors beneath it, as the registry has them.
fn rendered() -> String {
    let mut table =
        String::from("| # | status | call | where | disposition |\n|---|---|---|---|---|\n");
    for cells in section("rows", &ROW_COLUMNS) {
        table.push_str(&format!("| {} |\n", cells.join(" | ")));
    }
    table.push_str(
        "\n**The doors** — one `bt_platform::admission::doors` type per line of the registry's \
         `# doors` section; the station is the `hang_watch` station its meter enters. Every door \
         takes its token by value, minted where the line says (A1d).\n\n",
    );
    table.push_str(
        "| door | row | station | admitted in | call | minted at | measures |\n\
         |---|---|---|---|---|---|---|\n",
    );
    for cells in section("doors", &DOOR_COLUMNS) {
        table.push_str(&format!(
            "| `{}` | {} | `{}` | {} | {} | {} | {} |\n",
            cells[0], cells[1], cells[2], cells[3], cells[4], cells[5], cells[6]
        ));
    }
    table
}

/// §5.5's table, as the registry's `# completions` section has it.
fn rendered_completions() -> String {
    let mut table = String::from(
        "| class | door | thread | signal | failure | supersession | sink | status |\n\
         |---|---|---|---|---|---|---|---|\n",
    );
    for cells in section("completions", &COMPLETION_COLUMNS) {
        table.push_str(&format!(
            "| {} | `{}` | {} | {} | {} | {} | {} | {} |\n",
            cells[0], cells[1], cells[2], cells[3], cells[4], cells[5], cells[6], cells[7]
        ));
    }
    table
}

/// The text between `begin` and `end` in `document`, against `wanted`; the first line that
/// differs, said with its number, or `None`.
fn region_differs(
    document: &str,
    begin: &str,
    end: &str,
    wanted: &str,
    what: &str,
) -> Option<String> {
    let from = document
        .find(begin)
        .unwrap_or_else(|| panic!("ARCHITECTURE.md has {what}'s opening marker"))
        + begin.len();
    let to = from
        + document[from..]
            .find(end)
            .unwrap_or_else(|| panic!("and {what}'s closing marker, after it"));
    let held = &document[from..to];
    if held == wanted {
        return None;
    }
    let (number, held_line, wanted_line) = held
        .lines()
        .map(Some)
        .chain(std::iter::repeat(None))
        .zip(wanted.lines().map(Some).chain(std::iter::repeat(None)))
        .take(held.lines().count().max(wanted.lines().count()) + 1)
        .enumerate()
        .find(|(_, (held_line, wanted_line))| held_line != wanted_line)
        .map_or((0, None, None), |(index, (held_line, wanted_line))| {
            (index + 1, held_line, wanted_line)
        });
    Some(format!(
        "{what}, line {number}, is not what window_waits.tsv says — run \
         scripts/dev/generate-window-waits-table.ps1\n  the document: {}\n  the registry: {}",
        held_line.unwrap_or("<end of the table>"),
        wanted_line.unwrap_or("<end of the table>")
    ))
}

fn repository_root() -> PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .canonicalize()
        .expect("this crate sits two directories below the workspace root")
}

/// RED (A1a, budget note R7; S-1) — **`docs/ARCHITECTURE.md` §5.3's table and §5.5's completions
/// ledger are the registry.**
///
/// Each table is rendered from `window_waits.tsv` and compared with the one between its markers;
/// the renderings are left in `target/window-waits-table.md` and
/// `target/window-waits-completions.md`, which `scripts/dev/generate-window-waits-table.ps1`
/// copies into the document. One list, so the prose
/// and the registry cannot disagree while every check passes.
///
/// MUTATION: edit a status in the registry and not the document (or the reverse) and it goes red.
#[test]
fn the_architecture_table_is_the_registry() {
    let root = repository_root();
    let target = root.join("target");
    std::fs::create_dir_all(&target).expect("the workspace has a target directory");
    let wanted = rendered();
    let completions = rendered_completions();
    std::fs::write(target.join("window-waits-table.md"), wanted.as_bytes())
        .expect("target/ is writable");
    std::fs::write(
        target.join("window-waits-completions.md"),
        completions.as_bytes(),
    )
    .expect("target/ is writable");
    let document = std::fs::read_to_string(root.join("docs").join("ARCHITECTURE.md"))
        .expect("docs/ARCHITECTURE.md is checked in")
        .replace("\r\n", "\n");
    let differences: Vec<String> = [
        (BEGIN, END, wanted.as_str(), "ARCHITECTURE §5.3's table"),
        (
            COMPLETIONS_BEGIN,
            COMPLETIONS_END,
            completions.as_str(),
            "ARCHITECTURE §5.5's completions ledger",
        ),
    ]
    .into_iter()
    .filter_map(|(begin, end, wanted, what)| region_differs(&document, begin, end, wanted, what))
    .collect();
    assert!(differences.is_empty(), "{}", differences.join("\n"));
}

// ─────────────────────────────────────────────────────────────────────────────────────────────
// The source guard's prohibitions (A1e; design note 2026-09-26 §9.1 as amended by (c)4, (c)8,
// (d)4, (e)3, (f)1, (f)2 and (g); budget note §C-2, §C-3, §C-5)
// ─────────────────────────────────────────────────────────────────────────────────────────────
//
// Everything below reads Folio's own source through `bt_source`, over a declared universe: the
// product is `bt-app` and every first-party package its manifests reach (`product`),
// each package's own `src/` as `Index::of_package` lowers it, `vendor/` excluded; within it, only
// a product target's file (a library, or `bt-app`'s `folio` binary — never a development binary
// under `src/bin/`) and only an item standing on an arm a product build compiles
// (`Occurrence::in_the_product`), so test modules are out by their declaration. The reading is
// `cfg`-blind, so every platform's arm is read on every host.

/// The first-party packages that are not in `folio.exe`: development tools, and `bt-testpath`,
/// which only tests and the test-support features name. Every other workspace member outside
/// `vendor/` must be one `bt-app` depends on.
const NOT_THE_PRODUCT: [&str; 5] = [
    "bt-corpus",
    "bt-lint-probe",
    "bt-render-probe",
    "bt-source",
    "bt-testpath",
];

/// **The product as a build of `folio.exe` sees it**: the first-party packages in it, each with
/// the first-party packages its product code can name (its *product* dependency edges), and the
/// features that build turns on in each ([`resolve_product`]).
#[derive(Debug)]
struct Product {
    /// Every product package, sorted, with its direct first-party product dependencies.
    packages: Vec<(String, Vec<String>)>,
    /// The features a product build turns on, per product package.
    features: BTreeMap<String, BTreeSet<String>>,
}

/// The dependency tables a build of the package itself compiles in: `[dependencies]` and every
/// `[target.….dependencies]`. `[dev-dependencies]` and `[build-dependencies]` are not among them.
fn dependency_tables(document: &toml_edit::DocumentMut) -> Vec<&dyn toml_edit::TableLike> {
    let mut tables = Vec::new();
    if let Some(table) = document
        .get("dependencies")
        .and_then(toml_edit::Item::as_table_like)
    {
        tables.push(table);
    }
    if let Some(targets) = document
        .get("target")
        .and_then(toml_edit::Item::as_table_like)
    {
        for (_, target) in targets.iter() {
            if let Some(table) = target
                .get("dependencies")
                .and_then(toml_edit::Item::as_table_like)
            {
                tables.push(table);
            }
        }
    }
    tables
}

/// The package a dependency entry written under `key` names (`package = …` when renamed).
fn dependency_package(key: &str, entry: &toml_edit::Item) -> String {
    entry
        .as_table_like()
        .and_then(|detail| detail.get("package"))
        .and_then(toml_edit::Item::as_str)
        .unwrap_or(key)
        .to_owned()
}

/// **The product**, read off the workspace's manifests: every first-party package a dependency
/// table of `bt-app` reaches, however indirectly and whether optional or not, is a candidate, and
/// [`resolve_product`] decides which of them, and which of their edges, a build of `folio.exe`
/// actually has.
fn product() -> Product {
    resolve_product("bt-app", &product_candidate_manifests())
}

/// The text of every candidate manifest [`product`] resolves, by package name.
fn product_candidate_manifests() -> BTreeMap<String, String> {
    let root = repository_root();
    let workspace = bt_source::Workspace::read(&root).expect("the workspace's manifests");
    let mut manifests: BTreeMap<String, String> = BTreeMap::new();
    let mut queue = vec!["bt-app".to_owned()];
    while let Some(name) = queue.pop() {
        if manifests.contains_key(&name) {
            continue;
        }
        let package = workspace.package(&name).expect("a workspace package");
        let text = std::fs::read_to_string(package.directory().join("Cargo.toml"))
            .expect("a package has a manifest");
        let document: toml_edit::DocumentMut = text
            .parse()
            .unwrap_or_else(|error| panic!("{name}'s manifest is TOML: {error}"));
        for table in dependency_tables(&document) {
            for (key, entry) in table.iter() {
                let dependency = dependency_package(key, entry);
                if workspace
                    .package(&dependency)
                    .is_ok_and(|package| !bt_source::is_vendored(package.directory()))
                {
                    queue.push(dependency);
                }
            }
        }
        manifests.insert(name, text);
    }
    manifests
}

/// Cargo's own resolution of a build of `root` with its default features, over `manifests` (the
/// candidates; a manifest no product edge reaches stays out). A dependency in `[dependencies]` or
/// a `[target.….dependencies]` table, in any TOML form — inline, multi-line, or a
/// `[dependencies.name]` table — and under its `package = …` name when it is renamed, is a product
/// edge when it is not `optional`, or when a feature the build turns on in its dependent activates
/// it: `dep:key`, `key/feature` (not `key?/feature`), or the implicit feature `key` of a package
/// that never writes `dep:key`. A product edge contributes the features it names and, unless
/// `default-features = false`, its `default`; a feature implies each entry of its `[features]`
/// row — another feature of the same package, or `dep/feature` / `dep?/feature` in a dependency —
/// until nothing changes. `[dev-dependencies]` and `[build-dependencies]` contribute nothing: a
/// product build compiles neither into the product, and an optional dependency only a test-only
/// feature activates is not in it either.
fn resolve_product(root: &str, manifests: &BTreeMap<String, String>) -> Product {
    let documents: BTreeMap<&str, toml_edit::DocumentMut> = manifests
        .iter()
        .map(|(name, text)| {
            let document: toml_edit::DocumentMut = text
                .parse()
                .unwrap_or_else(|error| panic!("{name}'s manifest is TOML: {error}"));
            (name.as_str(), document)
        })
        .collect();

    // Every dependency edge between candidates: (dependent, the key it is written under,
    // package, features named, default features on, optional).
    struct Edge {
        from: String,
        key: String,
        package: String,
        features: Vec<String>,
        defaults: bool,
        optional: bool,
    }
    let strings = |item: Option<&toml_edit::Item>| -> Vec<String> {
        item.and_then(toml_edit::Item::as_array)
            .map(|array| {
                array
                    .iter()
                    .filter_map(|value| value.as_str().map(ToOwned::to_owned))
                    .collect()
            })
            .unwrap_or_default()
    };
    let mut edges: Vec<Edge> = Vec::new();
    for (name, document) in &documents {
        for table in dependency_tables(document) {
            for (key, entry) in table.iter() {
                let package = dependency_package(key, entry);
                let detail = entry.as_table_like();
                let flag = |field: &str| {
                    detail
                        .and_then(|detail| detail.get(field))
                        .and_then(toml_edit::Item::as_bool)
                };
                if documents.contains_key(package.as_str()) {
                    edges.push(Edge {
                        from: (*name).to_owned(),
                        key: key.to_owned(),
                        package,
                        features: strings(detail.and_then(|detail| detail.get("features"))),
                        defaults: flag("default-features").unwrap_or(true),
                        optional: flag("optional").unwrap_or(false),
                    });
                }
            }
        }
    }

    let features_table = |package: &str| {
        documents
            .get(package)
            .and_then(|document| document.get("features"))
            .and_then(toml_edit::Item::as_table_like)
    };
    // Whether `package` ever writes `dep:key`, which removes the implicit feature `key`.
    let writes_dep = |package: &str, key: &str| {
        features_table(package).is_some_and(|table| {
            table.iter().any(|(_, row)| {
                strings(Some(row))
                    .iter()
                    .any(|e| *e == format!("dep:{key}"))
            })
        })
    };
    let implicit = |package: &str, feature: &str| {
        edges
            .iter()
            .any(|edge| edge.from == package && edge.key == feature && edge.optional)
            && !writes_dep(package, feature)
    };
    let declares = |package: &str, feature: &str| {
        features_table(package).is_some_and(|table| table.get(feature).is_some())
            || implicit(package, feature)
    };
    let implies = |package: &str, feature: &str| -> Vec<String> {
        match features_table(package).and_then(|table| table.get(feature)) {
            Some(row) => strings(Some(row)),
            None if implicit(package, feature) => vec![format!("dep:{feature}")],
            None => Vec::new(),
        }
    };

    let mut enabled: BTreeMap<String, BTreeSet<String>> = documents
        .keys()
        .map(|name| ((*name).to_owned(), BTreeSet::new()))
        .collect();
    let turn_on =
        |enabled: &mut BTreeMap<String, BTreeSet<String>>, package: &str, feature: &str| {
            declares(package, feature)
                && enabled
                    .get_mut(package)
                    .is_some_and(|set| set.insert(feature.to_owned()))
        };
    let mut in_product: BTreeSet<String> = BTreeSet::from([root.to_owned()]);
    let mut activated: BTreeSet<(String, String)> = BTreeSet::new();
    turn_on(&mut enabled, root, "default");
    // A fixed point: features activate optional edges, and edges bring packages and features in.
    loop {
        let mut changed = false;
        let on: Vec<(String, String)> = enabled
            .iter()
            .flat_map(|(package, set)| set.iter().map(|f| (package.clone(), f.clone())))
            .collect();
        for (package, feature) in on {
            for implied in implies(&package, &feature) {
                if let Some(key) = implied.strip_prefix("dep:") {
                    changed |= activated.insert((package.clone(), key.to_owned()));
                    continue;
                }
                match implied.split_once('/') {
                    Some((key, dependency_feature)) => {
                        let weak = key.ends_with('?');
                        let key = key.trim_end_matches('?');
                        if !weak {
                            changed |= activated.insert((package.clone(), key.to_owned()));
                        }
                        let targets: Vec<String> = edges
                            .iter()
                            .filter(|edge| {
                                edge.from == package
                                    && edge.key == key
                                    && (!edge.optional
                                        || activated.contains(&(package.clone(), key.to_owned())))
                            })
                            .map(|edge| edge.package.clone())
                            .collect();
                        for target in targets {
                            changed |= turn_on(&mut enabled, &target, dependency_feature);
                        }
                    }
                    None => changed |= turn_on(&mut enabled, &package, &implied),
                }
            }
        }
        for edge in &edges {
            let live = in_product.contains(&edge.from)
                && (!edge.optional || activated.contains(&(edge.from.clone(), edge.key.clone())));
            if !live {
                continue;
            }
            changed |= in_product.insert(edge.package.clone());
            if edge.defaults {
                changed |= turn_on(&mut enabled, &edge.package, "default");
            }
            for feature in &edge.features {
                changed |= turn_on(&mut enabled, &edge.package, feature);
            }
        }
        if !changed {
            break;
        }
    }

    let packages = in_product
        .iter()
        .map(|name| {
            let dependencies: BTreeSet<String> = edges
                .iter()
                .filter(|edge| {
                    edge.from == *name
                        && (!edge.optional
                            || activated.contains(&(edge.from.clone(), edge.key.clone())))
                })
                .map(|edge| edge.package.clone())
                .collect();
            (name.clone(), dependencies.into_iter().collect())
        })
        .collect();
    enabled.retain(|name, _| in_product.contains(name));
    Product {
        packages,
        features: enabled,
    }
}

/// What a `cfg` predicate says about a product build that has `features` on: `test` is off, a
/// feature is on exactly when it is in `features`, anything else (a platform) is unknown —
/// three-valued over `not`, `all` and `any`, as `bt_source`'s own reading is.
fn product_build_cfg(meta: &syn::Meta, features: &BTreeSet<String>) -> Option<bool> {
    if meta.path().is_ident("test") {
        return Some(false);
    }
    match meta {
        syn::Meta::NameValue(pair) if pair.path.is_ident("feature") => match &pair.value {
            syn::Expr::Lit(syn::ExprLit {
                lit: syn::Lit::Str(name),
                ..
            }) => Some(features.contains(&name.value())),
            _ => None,
        },
        syn::Meta::List(list) => {
            let children = list
                .parse_args_with(
                    syn::punctuated::Punctuated::<syn::Meta, syn::Token![,]>::parse_terminated,
                )
                .ok()?;
            let values: Vec<_> = children
                .iter()
                .map(|child| product_build_cfg(child, features))
                .collect();
            if list.path.is_ident("not") && values.len() == 1 {
                values[0].map(|value| !value)
            } else if list.path.is_ident("all") {
                if values.contains(&Some(false)) {
                    Some(false)
                } else if values.iter().all(|value| *value == Some(true)) {
                    Some(true)
                } else {
                    None
                }
            } else if list.path.is_ident("any") {
                if values.contains(&Some(true)) {
                    Some(true)
                } else if values.iter().all(|value| *value == Some(false)) {
                    Some(false)
                } else {
                    None
                }
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Whether every predicate on a path lets a product build with `features` compile it.
fn product_build_permits(predicates: &[String], features: &BTreeSet<String>) -> bool {
    predicates.iter().all(|predicate| {
        syn::parse_str::<syn::Meta>(predicate).map_or(true, |meta| {
            product_build_cfg(&meta, features) != Some(false)
        })
    })
}

fn manifests(rows: &[(&str, &str)]) -> BTreeMap<String, String> {
    rows.iter()
        .map(|(name, text)| ((*name).to_owned(), (*text).to_owned()))
        .collect()
}

fn enabled_in(resolved: &BTreeMap<String, BTreeSet<String>>, package: &str) -> Vec<String> {
    resolved
        .get(package)
        .map(|set| set.iter().cloned().collect())
        .unwrap_or_default()
}

/// RED (T-TEST-SHELL-HYGIENE review) — **a product build's features are resolved the way cargo
/// resolves them, whatever TOML shape the manifests are written in.**
///
/// The root's `default` turns on `wide`, which turns on `renamed/deep` (`bt-b`, under a renamed
/// key) across the crate boundary and, through `bt-c?/quiet`, `bt-c`'s `quiet`; `bt-b`'s
/// dependency on `bt-c` is a `[dependencies.bt-c]` table naming `loud` and `louder` in a
/// multi-line array; the root names `bt-b`'s `first` and `second` in a multi-line array inside
/// an inline table. A
/// dev-dependency's `tests-only` and a build-dependency's `build-only` stay off, and so does
/// `bt-c`'s `default` (its edge says `default-features = false`).
///
/// MUTATIONS: read only a `features` array's first element (`strings` takes one) and `second`
/// and `louder` are lost; skip the `dep/feature` arm and `deep` and `quiet` stay off;
/// read `[dev-dependencies]` as a product table and `tests-only` turns on; ignore
/// `default-features` and `bt-c`'s `default` turns on.
#[test]
fn product_features_follow_cargo_across_every_manifest_shape() {
    let resolved = resolve_product(
        "bt-a",
        &manifests(&[
            (
                "bt-a",
                r#"[package]
name = "bt-a"

[features]
default = ["wide"]
wide = ["renamed/deep", "bt-c?/quiet"]

[dependencies]
renamed = { package = "bt-b", path = "../bt-b", features = [
    "first",
    "second",
] }
bt-c = { path = "../bt-c", default-features = false }

[dev-dependencies]
bt-b = { path = "../bt-b", features = ["tests-only"] }

[build-dependencies]
bt-c = { path = "../bt-c", features = ["build-only"] }
"#,
            ),
            (
                "bt-b",
                r#"[package]
name = "bt-b"

[features]
first = []
second = []
deep = []
tests-only = []

[dependencies.bt-c]
path = "../bt-c"
default-features = false
features = [
    "loud",
    "louder",
]
"#,
            ),
            (
                "bt-c",
                r#"[package]
name = "bt-c"

[features]
default = ["chatty"]
chatty = []
loud = []
louder = []
quiet = []
build-only = []
"#,
            ),
        ]),
    )
    .features;
    assert_eq!(enabled_in(&resolved, "bt-a"), ["default", "wide"]);
    assert_eq!(
        enabled_in(&resolved, "bt-b"),
        ["deep", "first", "second"],
        "named in a multi-line array under a renamed key, and implied across the crate boundary"
    );
    assert_eq!(
        enabled_in(&resolved, "bt-c"),
        ["loud", "louder", "quiet"],
        "named in a `[dependencies.bt-c]` table, implied through `bt-c?/quiet`, and no default"
    );
}

/// RED (T-TEST-SHELL-HYGIENE review) — **this workspace's test-only features are off in the
/// product**, read from the real manifests: `bt-pty`'s `test-shell` and `bt-platform`'s
/// `trust-harness` are named only on dev-dependency lines.
///
/// MUTATION: read `[dev-dependencies]` as a product table and both turn on.
#[test]
fn the_workspace_s_test_only_features_are_off_in_the_product() {
    let resolved = product().features;
    for (package, feature) in [("bt-pty", "test-shell"), ("bt-platform", "trust-harness")] {
        assert!(
            !enabled_in(&resolved, package)
                .iter()
                .any(|on| on == feature),
            "{package}'s {feature} is on in a build of folio.exe: {resolved:?}"
        );
    }
}

/// RED (T-PROBE-CHILD round 4) — **a product build's dependency edges are the ones cargo builds
/// into it**: a non-optional edge, an optional one a product feature activates (`dep:key`, or the
/// implicit feature `key`); not a dev-dependency, not an optional one only a test-only feature
/// activates, and not one only a weak `key?/feature` names.
///
/// MUTATION: in `resolve_product`, treat every edge as live whether `optional` or not; `bt-b`
/// becomes a product package and a product edge of `bt-a`.
#[test]
fn an_edge_only_a_test_build_activates_is_no_product_edge() {
    let resolved = resolve_product(
        "bt-a",
        &manifests(&[
            (
                "bt-a",
                r#"[package]
name = "bt-a"

[features]
default = ["wide"]
wide = ["dep:bt-d", "bt-f", "bt-b?/loud"]
test-shell = ["dep:bt-b"]

[dependencies]
bt-b = { path = "../bt-b", optional = true }
bt-c = { path = "../bt-c" }
bt-d = { path = "../bt-d", optional = true }
bt-f = { path = "../bt-f", optional = true }

[dev-dependencies]
bt-a = { path = ".", features = ["test-shell"] }
bt-b = { path = "../bt-b" }
"#,
            ),
            (
                "bt-b",
                "[package]\nname = \"bt-b\"\n\n[features]\nloud = []\n",
            ),
            ("bt-c", "[package]\nname = \"bt-c\"\n"),
            ("bt-d", "[package]\nname = \"bt-d\"\n"),
            ("bt-f", "[package]\nname = \"bt-f\"\n"),
        ]),
    );
    assert_eq!(
        resolved.packages,
        [
            (
                "bt-a".to_owned(),
                vec!["bt-c".to_owned(), "bt-d".to_owned(), "bt-f".to_owned()]
            ),
            ("bt-c".to_owned(), Vec::new()),
            ("bt-d".to_owned(), Vec::new()),
            ("bt-f".to_owned(), Vec::new()),
        ],
        "`bt-b` is reached only by a dev-dependency, a test-only feature and a weak feature"
    );
    assert_eq!(
        enabled_in(&resolved.features, "bt-a"),
        ["bt-f", "default", "wide"]
    );
}

/// The first-party items `site_name` calls in `body` resolve to, in `world`, by key.
fn callees_in(world: &World, body: &str, site_name: &str) -> Vec<String> {
    let (src, record) = world
        .srcs
        .iter()
        .enumerate()
        .find_map(|(at, src)| {
            src.index
                .items()
                .iter()
                .find(|record| {
                    record.kind().is_callable()
                        && src.product_item(record)
                        && key_of(src, record) == body
                })
                .map(|record| (at, record))
        })
        .unwrap_or_else(|| panic!("`{body}` is a product body"));
    let body = Body::new(world, src, record);
    let sites: Vec<Site> = body
        .sites()
        .into_iter()
        .filter(|site| site.name == site_name)
        .collect();
    assert!(!sites.is_empty(), "`{site_name}` is called in the body");
    sites
        .iter()
        .flat_map(|site| body.resolve(site))
        .map(|callable| world.key(&callable))
        .collect()
}

// Parsed by the guard but deliberately absent from the Rust build: these source shapes include
// calls Rust would reject precisely because the guard must not infer the receiver's type.
#[cfg(any())]
struct ReceiverTypingSourceShapes {
    typed_field: CappedReads,
    boxed_driver: Box<dyn crate::update_job::Driver>,
}

#[cfg(any())]
impl ReceiverTypingSourceShapes {
    fn receiver_typing_source_shapes(&mut self) {
        self.typed_field.observe(0);

        let annotated: CappedReads = unreachable!();
        annotated.observe(0);

        let chained_constructor = CappedReads::new(unreachable!(), 1).observe(0);
        chained_constructor.kill();
        let constructor_later = passthrough(CappedReads::new(unreachable!(), 1));
        constructor_later.kill();
        let factory = Pending::new(None, Vec::new());
        factory.kill();

        let mut reassigned: CappedReads = unreachable!();
        reassigned = unreachable!();
        reassigned.kill();

        let shadow_let: CappedReads = unreachable!();
        let shadow_let = unreachable!();
        shadow_let.kill();

        let shadow_closure: CappedReads = unreachable!();
        let _ = |shadow_closure| shadow_closure;
        shadow_closure.kill();

        let shadow_for: CappedReads = unreachable!();
        for shadow_for in unreachable!() {
            drop(shadow_for);
        }
        shadow_for.kill();

        let shadow_match: CappedReads = unreachable!();
        match unreachable!() {
            shadow_match => drop(shadow_match),
        }
        shadow_match.kill();

        let shadow_if: CappedReads = unreachable!();
        if let Some(shadow_if) = unreachable!() {
            drop(shadow_if);
        }
        shadow_if.kill();

        let slice: &[CappedReads] = unreachable!();
        slice.kill();
        let array: [CappedReads; 2] = unreachable!();
        array.kill();
        let option: Option<CappedReads> = unreachable!();
        option.kill();
        let boxed: Box<CappedReads> = unreachable!();
        boxed.kill();
        let generic: CappedReads<Vec<u8>> = unreachable!();
        generic.kill();

        type ReadsAlias = CappedReads;
        let alias: ReadsAlias = unreachable!();
        alias.kill();

        let ambiguous: Pending = unreachable!();
        ambiguous.kill();

        let trait_method: FileAnimationSource = unreachable!();
        trait_method.restart();

        let deref_reached: Runtime = unreachable!();
        deref_reached.preview_here(unreachable!());

        let macro_wrapped = Pending::new(None, Vec::new());
        passthrough!(macro_wrapped.kill());
    }

    fn trait_shape_field(&self) {
        let _ = self
            .boxed_driver
            .prepare(unreachable!(), unreachable!(), unreachable!());
    }
}

fn source_shape_body<'a>(world: &'a World) -> Body<'a> {
    let (src, record) = world
        .srcs
        .iter()
        .enumerate()
        .find_map(|(src, source)| {
            source
                .index
                .items()
                .iter()
                .find(|record| record.name() == "receiver_typing_source_shapes")
                .map(|record| (src, record))
        })
        .expect("the cfg-false source-shape fixture is indexed");
    Body::new(world, src, record)
}

/// RED (T-GUARDS-BLIND round 3) — the complete receiver-shape table. Only a direct `self.field`
/// with one restricted written field type and a uniquely bound, never-assigned annotated local
/// have a type. Every other row equals the pre-ticket reachable method-name match.
///
/// MUTATIONS, in table order: infer the leading constructor; scan for a later constructor; infer
/// factory returns; ignore assignment; count only `let` shadowing; ignore closure, `for`, match-arm,
/// or `if let` bindings; peel slice, array, `Option`, `Box`, or generic interiors; resolve aliases;
/// union same-named types; retain a first-party trait method; retain a `Deref` type; inspect through
/// a macro argument. Each mutation types its named row and makes the `receiver_types` assertion
/// red. Removing annotation typing or `self.field` typing makes the corresponding positive row red;
/// returning an empty preferred set instead of [`nonempty_or`] makes a name-match equality red.
#[test]
fn receiver_typing_only_narrows_a_non_empty_source_stated_answer() {
    let world = World::new();
    let body = source_shape_body(&world);
    let shapes = [
        ("self", "observe", true, "remove self-field typing"),
        (
            "annotated",
            "observe",
            true,
            "remove annotated-local typing",
        ),
        (
            "chained_constructor",
            "kill",
            false,
            "infer a leading chained constructor",
        ),
        (
            "constructor_later",
            "kill",
            false,
            "scan for a later constructor",
        ),
        ("factory", "kill", false, "infer a factory return"),
        ("reassigned", "kill", false, "ignore assignment targets"),
        ("shadow_let", "kill", false, "ignore a second let binding"),
        ("shadow_closure", "kill", false, "ignore closure parameters"),
        ("shadow_for", "kill", false, "ignore for-pattern bindings"),
        ("shadow_match", "kill", false, "ignore match-arm bindings"),
        ("shadow_if", "kill", false, "ignore if-let bindings"),
        ("slice", "kill", false, "peel a slice interior"),
        ("array", "kill", false, "peel an array interior"),
        ("option", "kill", false, "peel Option's argument"),
        ("boxed", "kill", false, "peel Box's argument"),
        ("generic", "kill", false, "ignore generic arguments"),
        ("alias", "kill", false, "resolve a type alias"),
        (
            "ambiguous",
            "kill",
            false,
            "union same-named first-party types",
        ),
        (
            "trait_method",
            "restart",
            false,
            "retain a first-party trait receiver",
        ),
        (
            "deref_reached",
            "preview_here",
            false,
            "retain a Deref receiver",
        ),
        (
            "macro_wrapped",
            "kill",
            false,
            "infer through a macro argument",
        ),
    ];
    let sites = body.sites();
    for (receiver, method, typed, mutation) in shapes {
        let site = sites
            .iter()
            .find(|site| {
                site.name == method
                    && matches!(&site.form, Form::Method(Some(chain)) if chain[0] == receiver)
            })
            .unwrap_or_else(|| panic!("the `{receiver}.{method}` fixture call is indexed"));
        assert_eq!(
            body.receiver_types(site).is_some(),
            typed,
            "the `{receiver}.{method}` row has the promised typing; RED mutation: {mutation}"
        );
        let resolved: BTreeSet<String> = body
            .resolve(site)
            .iter()
            .map(|callable| world.key(callable))
            .collect();
        if typed {
            assert_eq!(
                resolved,
                BTreeSet::from(["bt-pty crate::CappedReads::observe".to_owned()]),
                "the `{receiver}.{method}` row narrows to its written type"
            );
        } else {
            let named: BTreeSet<String> = world
                .callables
                .get(method)
                .into_iter()
                .flatten()
                .filter(|callable| {
                    world.reach[body.src].contains(&callable.src) && callable.type_owner.is_some()
                })
                .map(|callable| world.key(callable))
                .collect();
            assert_eq!(resolved, named, "`{receiver}.{method}` stays name-matched");
        }
    }
}

/// AUDIT (T-GUARDS-BLIND round 3) — the real-tree diff against the pre-round-1 local-receiver
/// rule. Direct `self.field` typing already existed at that baseline, so only a newly typed local
/// can shrink the answer. Every such row is nonempty and drops only methods owned by another type;
/// the count and rows are printed for the ticket report. The fixture above supplies the RED proof
/// for both permitted cases even when the real tree has no newly narrowed local today.
#[test]
fn real_tree_receiver_narrowing_only_removes_other_types_methods() {
    let world = World::new();
    let mut shrinks = Vec::new();
    for (src_at, src) in world.srcs.iter().enumerate() {
        let reach = &world.reach[src_at];
        for record in src
            .index
            .items()
            .iter()
            .filter(|record| record.kind().is_callable() && src.product_item(record))
        {
            let body = Body::new(&world, src_at, record);
            for site in body.sites() {
                let Form::Method(Some(chain)) = &site.form else {
                    continue;
                };
                if chain.len() != 1 || !body.locals.contains_key(chain[0]) {
                    continue;
                }
                let Some(types) = body.receiver_types(&site) else {
                    continue;
                };
                let before: BTreeSet<String> = world
                    .callables
                    .get(site.name)
                    .into_iter()
                    .flatten()
                    .filter(|callable| {
                        reach.contains(&callable.src) && callable.type_owner.is_some()
                    })
                    .map(|callable| world.key(callable))
                    .collect();
                let after: BTreeSet<String> = body
                    .resolve(&site)
                    .iter()
                    .map(|callable| world.key(callable))
                    .collect();
                if before == after || !after.is_subset(&before) {
                    continue;
                }
                assert!(!after.is_empty(), "typing may never narrow to empty");
                let removed: Vec<String> = before.difference(&after).cloned().collect();
                for callable in world
                    .callables
                    .get(site.name)
                    .into_iter()
                    .flatten()
                    .filter(|callable| removed.contains(&world.key(callable)))
                {
                    assert!(
                        callable
                            .type_owner
                            .as_ref()
                            .is_some_and(|owner| !types.contains(owner)),
                        "{} lost a method of its own stated type {types:?}",
                        src.location(site.at)
                    );
                }
                shrinks.push(format!(
                    "{}\t{}\t{}\t{}\t{}\t{}",
                    key_of(src, record),
                    src.location(site.at),
                    chain.join("."),
                    types.iter().cloned().collect::<Vec<_>>().join("|"),
                    after.iter().cloned().collect::<Vec<_>>().join("|"),
                    removed.join("|")
                ));
            }
        }
    }
    eprintln!("CALLEE_SHRINK_COUNT\t{}", shrinks.len());
    for row in shrinks {
        eprintln!("CALLEE_SHRINK\t{row}");
    }
}

/// RED (T-PROBE-CHILD round 4, T-GUARDS-BLIND) — **a receiver whose field declaration writes
/// its type does not become every method with the same name**: `PtySession::shutdown` binds
/// `child` from `self.child`, but that unannotated local is deliberately untyped. In the
/// real graph and with a dev-only edge `ProbeChild` is unreachable. With an artificial product
/// edge the tightened round-2 rule deliberately falls back to the name match, but the inventory
/// still attributes this source spelling to the registered `Child::kill` vocabulary effect before
/// treating it as a first-party edge. A real `ProbeChild` arm in `GitChild::kill` and the
/// name-matched `CappedReads::observe` call remain attributed to their actual callees.
///
/// MUTATIONS: infer a type from the `self.child.take()` initializer, and the product-edge collision
/// goes red; return no methods for an untyped local, and the `CappedReads` assertion goes red; give
/// every package only itself to reach, and the real `GitChild` attribution goes red.
#[test]
fn a_test_only_edge_lends_product_code_no_first_party_callee() {
    const PROBE_KILL: &str = "bt-platform crate::ProbeChild::kill";
    const OPTIONAL: &str = "bt-platform = { path = \"../bt-platform\", optional = true }";
    const FEATURE: &str = "test-shell = [\"dep:bt-platform\", \"dep:bt-testpath\"]";
    let real = product_candidate_manifests();
    let with_pty = |manifest: String| {
        let mut manifests = real.clone();
        manifests.insert("bt-pty".to_owned(), manifest);
        World::of(resolve_product("bt-app", &manifests))
    };
    let pty = &real["bt-pty"];
    assert_eq!(
        (pty.matches(OPTIONAL).count(), pty.matches(FEATURE).count()),
        (1, 1),
        "bt-pty's manifest still writes its test-only edge to bt-platform this way"
    );

    let as_written = World::new();
    let callees = callees_in(&as_written, PTY_SHUTDOWN, "kill");
    assert!(
        !callees.iter().any(|key| key == PROBE_KILL),
        "a test-only optional edge lent product code a callee: {callees:?}"
    );

    let dev_only = with_pty(
        pty.replace(OPTIONAL, "")
            .replace(FEATURE, "test-shell = []"),
    );
    let callees = callees_in(&dev_only, PTY_SHUTDOWN, "kill");
    assert!(
        !callees.iter().any(|key| key == PROBE_KILL),
        "a dev-dependency lent product code a callee: {callees:?}"
    );

    let product_edge = with_pty(
        pty.replace(OPTIONAL, "bt-platform = { path = \"../bt-platform\" }")
            .replace(FEATURE, "test-shell = []"),
    );
    let callees = callees_in(&product_edge, PTY_SHUTDOWN, "kill");
    assert!(
        callees.iter().any(|key| key == PROBE_KILL),
        "typed-empty must fall back to the old name match: {callees:?}"
    );

    let callees = callees_in(&as_written, "bt-app crate::git::GitChild::kill", "kill");
    assert!(
        callees.iter().any(|key| key == PROBE_KILL),
        "a real `ProbeChild` call is still attributed: {callees:?}"
    );

    let callees = callees_in(
        &as_written,
        "bt-pty crate::read_pty_output_without_dump",
        "observe",
    );
    assert!(
        callees
            .iter()
            .any(|key| key == "bt-pty crate::CappedReads::observe"),
        "an untyped constructor local still has its name-matched method: {callees:?}"
    );
}

/// RED (T-TEST-SHELL-HYGIENE review) — **a `cfg` predicate is read as a product build reads
/// it**: `test` off, a feature on exactly when the product turns it on, a platform unknown.
///
/// MUTATION: answer `None` for `feature = "…"` in `product_build_cfg` and the first, third and
/// fourth rows are unknown instead of decided.
#[test]
fn a_cfg_is_read_with_the_product_s_features() {
    let on: BTreeSet<String> = ["shipped".to_owned()].into_iter().collect();
    let read = |predicate: &str| {
        product_build_cfg(
            &syn::parse_str::<syn::Meta>(predicate).expect("a cfg predicate"),
            &on,
        )
    };
    for (predicate, expected) in [
        (r#"any(test, feature = "test-shell")"#, Some(false)),
        ("test", Some(false)),
        (r#"feature = "shipped""#, Some(true)),
        (r#"not(feature = "test-shell")"#, Some(true)),
        (r#"all(windows, feature = "test-shell")"#, Some(false)),
        (r#"any(unix, feature = "test-shell")"#, None),
        ("windows", None),
        (r#"all(windows, feature = "shipped")"#, None),
    ] {
        assert_eq!(read(predicate), expected, "{predicate}");
    }
    assert!(!product_build_permits(
        &[r#"any(test, feature = "test-shell")"#.to_owned()],
        &on
    ));
    assert!(product_build_permits(&["windows".to_owned()], &on));
}

// ── the lexer: code tokens, comments skipped, a literal one token ───────────────────────────

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind {
    Ident,
    Punct,
    Literal,
    Lifetime,
}

/// One code token, by its offsets in the index's union.
#[derive(Clone, Copy, Debug)]
struct Tok {
    kind: Kind,
    start: usize,
    end: usize,
}

/// One product package's index.
struct Src {
    package: &'static str,
    index: &'static Index,
    /// The features a product build turns on in this package ([`Product::features`]).
    features: &'static BTreeSet<String>,
}

/// The punctuation read as one token.
const JOINED: [&str; 12] = [
    "...", "..=", "::", "->", "=>", "..", "==", "!=", "<=", ">=", "&&", "||",
];

impl Src {
    fn text(&self, tok: Tok) -> &'static str {
        &self.index.union()[tok.start..tok.end]
    }

    /// Whether `tok` is code spelled `spelled`.
    fn is(&self, tok: Option<&Tok>, spelled: &str) -> bool {
        tok.is_some_and(|tok| tok.kind != Kind::Literal && self.text(*tok) == spelled)
    }

    fn file_end(&self, at: usize) -> usize {
        self.index
            .file_at(at)
            .map_or(self.index.union().len(), |file| file.span().end())
    }

    /// The code tokens of `[from, to)`: comments are skipped (they are the index's own masks), a
    /// literal is one token, and a name, a lifetime and the joined punctuation are one each.
    fn lex(&self, from: usize, to: usize) -> Vec<Tok> {
        let text = self.index.union();
        let bytes = text.as_bytes();
        let comments = self.index.comments();
        let literals = self.index.literals();
        let mut comment = comments.partition_point(|c| c.span().end() <= from);
        let mut literal = literals.partition_point(|l| l.span().end() <= from);
        let starts = |b: u8| b.is_ascii_alphabetic() || b == b'_' || b >= 0x80;
        let continues = |b: u8| b.is_ascii_alphanumeric() || b == b'_' || b >= 0x80;
        let word_end = |from: usize| {
            let mut end = from;
            while end < to && continues(bytes[end]) {
                end += 1;
            }
            end
        };
        let mut out = Vec::new();
        let mut at = from;
        while at < to {
            while comment < comments.len() && comments[comment].span().end() <= at {
                comment += 1;
            }
            if comment < comments.len() && comments[comment].span().start() <= at {
                at = comments[comment].span().end();
                continue;
            }
            while literal < literals.len() && literals[literal].span().end() <= at {
                literal += 1;
            }
            if literal < literals.len() && literals[literal].span().start() <= at {
                let span = literals[literal].span();
                out.push(Tok {
                    kind: Kind::Literal,
                    start: span.start(),
                    end: span.end(),
                });
                at = span.end();
                continue;
            }
            let byte = bytes[at];
            let (kind, start, end) = if byte.is_ascii_whitespace() {
                at += 1;
                continue;
            } else if byte == b'r'
                && bytes.get(at + 1) == Some(&b'#')
                && bytes.get(at + 2).is_some_and(|b| starts(*b))
            {
                (Kind::Ident, at + 2, word_end(at + 2))
            } else if starts(byte) {
                (Kind::Ident, at, word_end(at))
            } else if byte == b'\'' && bytes.get(at + 1).is_some_and(|b| starts(*b)) {
                (Kind::Lifetime, at + 1, word_end(at + 1))
            } else {
                let rest = &bytes[at..to];
                let width = JOINED
                    .iter()
                    .find(|joined| rest.starts_with(joined.as_bytes()))
                    .map_or_else(
                        || text[at..].chars().next().map_or(1, char::len_utf8),
                        |joined| joined.len(),
                    );
                (Kind::Punct, at, at + width)
            };
            out.push(Tok { kind, start, end });
            at = end;
        }
        out
    }

    /// The tokens of the bracketed group opening at `open`, delimiters included.
    fn group(&self, open: usize) -> Vec<Tok> {
        let end = self.file_end(open);
        let mut window = 4096;
        loop {
            let to = (open + window).min(end);
            let toks = self.lex(open, to);
            if let Some(close) = closing(self, &toks, 0) {
                return toks[..=close].to_vec();
            }
            if to == end {
                return toks;
            }
            window *= 4;
        }
    }

    /// Whether a file belongs to a product target: a library, or `bt-app`'s `folio` binary.
    fn product_file(&self, file: &FileRecord) -> bool {
        file.owners().iter().any(|owner| {
            owner.compilation.permits_product()
                && owner
                    .steps
                    .iter()
                    .all(|step| product_build_permits(&step.predicates, self.features))
                && match owner.target.kind {
                    TargetKind::Library => true,
                    TargetKind::Binary => self.package == "bt-app" && owner.target.name == "folio",
                    TargetKind::IntegrationTest
                    | TargetKind::Example
                    | TargetKind::Bench
                    | TargetKind::BuildScript => false,
                }
        })
    }

    /// Whether an item record is product code.
    fn product_item(&self, record: &ItemRecord) -> bool {
        self.product_file(self.index.file_of(record))
            && record.identities().any(|identity| {
                identity.variant.permits_product()
                    && product_build_permits(identity.variant.predicates(), self.features)
            })
    }

    /// Whether a build of the shipped program contains the token at `at`.
    fn in_product(&self, at: usize) -> bool {
        let Some(file) = self.index.file_at(at) else {
            return false;
        };
        if !self.product_file(file) {
            return false;
        }
        let tokens = self.index.tokens();
        let literals = self.index.literals();
        let token = tokens
            .get(tokens.partition_point(|t| t.span().end() <= at))
            .map(|t| t.span());
        let literal = literals
            .get(literals.partition_point(|l| l.span().end() <= at))
            .map(|l| l.span());
        let span = [token, literal]
            .into_iter()
            .flatten()
            .find(|span| span.holds(at) || span.start() >= at)
            .filter(|span| span.within(file.span()))
            .unwrap_or_else(|| file.span());
        Occurrence {
            span,
            certainty: Certainty::Resolved,
        }
        .in_the_product(self.index)
    }

    /// The smallest callable holding `at`.
    fn callable_at(&self, at: usize) -> Option<&'static ItemRecord> {
        self.index
            .items()
            .iter()
            .filter(|record| record.kind().is_callable() && record.whole().holds(at))
            .min_by_key(|record| record.whole().len())
    }

    /// The smallest module holding `at`, by its first path.
    fn module_at(&self, at: usize) -> &'static str {
        self.index
            .modules()
            .iter()
            .filter(|module| module.span().holds(at))
            .min_by_key(|module| module.span().len())
            .map_or("crate", |module| module.module_paths()[0].as_str())
    }

    /// Who owns the code at `at`: `bt-platform crate::macos_app::delegate_answers_the_dock_menu`,
    /// or the module when no function holds it (the inside of `define_class!`).
    fn owner_of(&self, at: usize) -> String {
        match self.callable_at(at) {
            Some(record) => format!("{} {}", self.package, name_of(record)),
            None => format!("{} {}", self.package, self.module_at(at)),
        }
    }

    fn location(&self, at: usize) -> String {
        self.index.locate(at).map_or_else(
            || format!("{} at byte {at}", self.package),
            |l| format!("{}:{}", l.file.display(), l.line),
        )
    }

    /// Every token spelled `name`, by its offset.
    fn named(&self, name: &str) -> Vec<usize> {
        self.index
            .tokens()
            .iter()
            .filter(|token| self.index.text(token.name_span()) == name)
            .map(|token| token.name_span().start())
            .collect()
    }

    /// The names spelled in `[from, to)`, out of `names`.
    fn names_in(&self, from: usize, to: usize, names: &[&str]) -> Vec<(usize, &'static str)> {
        let tokens = self.index.tokens();
        let first = tokens.partition_point(|t| t.span().start() < from);
        tokens[first..]
            .iter()
            .take_while(|t| t.span().start() < to)
            .map(|t| (t.name_span().start(), self.index.text(t.name_span())))
            .filter(|(_, name)| names.contains(name))
            .collect()
    }
}

/// The packages among `dependencies` that `src` re-exports to its own dependents: a product
/// `pub use dependency::…` (`pub use bt_effects::admission::*;`, `pub use bt_effects::file_reads;`),
/// the dependency named by its crate name. A `pub(crate) use` or a private `use` lends a dependent
/// nothing, and neither does a `use` in test code.
fn re_exported_by(src: &Src, dependencies: &BTreeSet<usize>, srcs: &[Src]) -> BTreeSet<usize> {
    dependencies
        .iter()
        .copied()
        .filter(|&dependency| {
            let crate_name = srcs[dependency].package.replace('-', "_");
            src.named(&crate_name).into_iter().any(|at| {
                let file_start = src.index.file_at(at).map_or(0, |f| f.span().start());
                let before = src.lex(at.saturating_sub(32).max(file_start), at);
                before.len() >= 2
                    && src.is(before.get(before.len() - 2), "pub")
                    && src.is(before.last(), "use")
                    && src.in_product(at)
            })
        })
        .collect()
}

/// `crate::x::Type::name`, by the item's first module path, without its arm.
fn name_of(record: &ItemRecord) -> String {
    let module = record.module_paths()[0];
    match record.type_owner() {
        Some(owner) => format!("{module}::{owner}::{}", record.name()),
        None => format!("{module}::{}", record.name()),
    }
}

/// `bt-pty crate::<PtySession as Drop>::drop`, with each predicate of the arm the item stands on
/// in brackets — `[windows]`, `[target_os = "macos"]` — when it has one: the key the tables below
/// name a body by.
fn key_of(src: &Src, record: &ItemRecord) -> String {
    let identity = record
        .identities()
        .next()
        .expect("an item is reached by a declaration");
    let mut key = format!("{} {}::", src.package, identity.module_path);
    match (&identity.type_owner, &identity.trait_name) {
        (Some(owner), Some(trait_name)) => key.push_str(&format!("<{owner} as {trait_name}>::")),
        (Some(owner), None) => key.push_str(&format!("{owner}::")),
        (None, Some(trait_name)) => key.push_str(&format!("{trait_name}::")),
        (None, None) => {}
    }
    key.push_str(&identity.name);
    for predicate in identity.variant.predicates() {
        key.push_str(&format!(" [{predicate}]"));
    }
    key
}

/// The index of the token closing the group `toks[open]` opens.
fn closing(src: &Src, toks: &[Tok], open: usize) -> Option<usize> {
    let mut depth = 0usize;
    for (at, tok) in toks.iter().enumerate().skip(open) {
        if tok.kind != Kind::Punct {
            continue;
        }
        match src.text(*tok) {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(at);
                }
            }
            _ => {}
        }
    }
    None
}

/// `a, b(c, d), e = "f"` split at its top-level commas.
fn split_commas(src: &Src, toks: &[Tok]) -> Vec<Vec<Tok>> {
    let mut parts = vec![Vec::new()];
    let mut depth = 0usize;
    for tok in toks {
        if tok.kind == Kind::Punct {
            match src.text(*tok) {
                "(" | "[" | "{" | "<" => depth += 1,
                ")" | "]" | "}" | ">" => depth = depth.saturating_sub(1),
                "," if depth == 0 => {
                    parts.push(Vec::new());
                    continue;
                }
                _ => {}
            }
        }
        if let Some(part) = parts.last_mut() {
            part.push(*tok);
        }
    }
    parts.retain(|part| !part.is_empty());
    parts
}

// ── attributes ─────────────────────────────────────────────────────────────────────────────

/// One attribute: `#[…]` or `#![…]`, and the tokens between its brackets.
struct Attribute {
    inner: bool,
    start: usize,
    body: Vec<Tok>,
}

/// Every attribute written in a package, product or not: a `#` in code followed by `[` or `![`.
fn attributes(src: &Src) -> Vec<Attribute> {
    let text = src.index.union();
    let bytes = text.as_bytes();
    let comments = src.index.comments();
    let literals = src.index.literals();
    let masked = |at: usize| {
        let comment = comments.partition_point(|c| c.span().end() <= at);
        let literal = literals.partition_point(|l| l.span().end() <= at);
        comments.get(comment).is_some_and(|c| c.span().holds(at))
            || literals.get(literal).is_some_and(|l| l.span().holds(at))
    };
    let skip_space = |mut at: usize| {
        while at < bytes.len() && bytes[at].is_ascii_whitespace() {
            at += 1;
        }
        at
    };
    let mut out = Vec::new();
    for (at, _) in text.match_indices('#') {
        let mut next = skip_space(at + 1);
        let inner = bytes.get(next) == Some(&b'!');
        if inner {
            next = skip_space(next + 1);
        }
        if bytes.get(next) != Some(&b'[') || masked(at) {
            continue;
        }
        let group = src.group(next);
        if group.len() >= 2 {
            out.push(Attribute {
                inner,
                start: at,
                body: group[1..group.len() - 1].to_vec(),
            });
        }
    }
    out
}

/// A path written as tokens, spaces dropped (`clippy :: style` is `clippy::style`), and how many
/// tokens it took.
fn path_of(src: &Src, toks: &[Tok]) -> (String, usize) {
    let mut path = String::new();
    let mut used = 0;
    for tok in toks {
        match tok.kind {
            Kind::Ident => path.push_str(src.text(*tok)),
            Kind::Punct if src.text(*tok) == "::" => path.push_str("::"),
            _ => break,
        }
        used += 1;
    }
    (path, used)
}

/// Every `allow`/`expect` an attribute says, however deep inside `cfg_attr`: (verb, lint).
fn suppressions(src: &Src, toks: &[Tok]) -> Vec<(String, String)> {
    let (path, used) = path_of(src, toks);
    let rest = &toks[used..];
    let args = match rest.first() {
        Some(open) if src.is(Some(open), "(") => &rest[1..rest.len().saturating_sub(1)],
        _ => return Vec::new(),
    };
    match path.as_str() {
        "allow" | "expect" => split_commas(src, args)
            .into_iter()
            .filter_map(|lint| {
                let (name, used) = path_of(src, &lint);
                (used == lint.len() && !name.is_empty()).then(|| (path.clone(), name))
            })
            .collect(),
        "cfg_attr" => split_commas(src, args)
            .into_iter()
            .skip(1)
            .flat_map(|attribute| suppressions(src, &attribute))
            .collect(),
        _ => Vec::new(),
    }
}

// ── the world: the product's callables and fields, and calls resolved to them ───────────────

/// A first-party function or method, or a `From::from` that `#[from]` generates.
#[derive(Clone, Debug)]
struct Callable {
    src: usize,
    module: String,
    type_owner: Option<String>,
    trait_name: Option<String>,
    /// `None` for a generated `From::from`, which no byte holds.
    record: Option<&'static ItemRecord>,
}

struct World {
    srcs: Vec<Src>,
    /// What each package's product code can name: itself, its direct first-party product
    /// dependencies ([`Product::packages`]) — a dev-dependency or a test-only optional one is not
    /// one — and every package one of those re-exports ([`re_exported_by`]): `bt-app` names
    /// `bt-effects`' admission through `bt_platform::admission`.
    reach: Vec<BTreeSet<usize>>,
    callables: HashMap<String, Vec<Callable>>,
    fields: HashMap<(String, String), Vec<(usize, &'static ItemRecord)>>,
    deref_types: BTreeSet<String>,
    /// Which trait a path names, over the product's packages.
    resolver: TraitResolver<'static>,
    /// The method items every trait declaration of the packages declares, by the trait's identity
    /// — with a default body or without.
    declared: BTreeMap<TraitId, Vec<(usize, &'static ItemRecord)>>,
    /// The product `impl` blocks of each first-party trait, by the trait's identity (the trait
    /// path each block writes, resolved in its own module), each with the product methods
    /// written in it.
    implementations: BTreeMap<TraitId, Vec<Implementation>>,
    /// **bt-source's call graph over the same packages** (T-BT-SOURCE-CALL-GRAPH), under the
    /// product's arms as this guard reads them ([`Src::product_item`]): what a door's reach is
    /// walked with ([`door_reach`]). Its packages are [`World::srcs`] in order, so an
    /// [`ItemId::package`] is a position in `srcs`.
    graph: Resolver<'static>,
    /// The product's `From::from` implementations: what an `.into()` reaches ([`followed`]).
    from_impls: Vec<ItemId>,
}

/// One product `impl` block of a first-party trait, and the product methods written in it.
struct Implementation {
    src: usize,
    block: &'static ImplRecord,
    methods: Vec<&'static ItemRecord>,
}

/// **What a decision of this guard takes from the resolver, or its refusal**: every trait the
/// guard decides with — the traits a product `impl` block implements ([`implemented`]), a trait's
/// supertraits ([`World::supertraits`]), the traits a receiver's stated type or a bound names
/// ([`Body::traits_named`]) — comes through here, and a path chained past the resolver's hop limit
/// ([`ResolveCutoff`]) fails the guard by name instead of being read as "no trait". A cycle among
/// `use`s and globs is no cutoff: it names nothing more. The refusal says the remedy: a shorter
/// re-export chain, or a larger hop limit in bt-source, raised with its reason.
fn decided(
    answer: Result<BTreeSet<TraitId>, ResolveCutoff>,
    what: impl FnOnce() -> String,
) -> BTreeSet<TraitId> {
    answer.unwrap_or_else(|ResolveCutoff(_)| {
        panic!(
            "{} chains past the resolver's hop limit — refused, never passed: shorten the \
             re-export chain, or raise `HOPS` in bt-source's `traits.rs` with its reason",
            what()
        )
    })
}

/// The first-party traits an `impl` block of `src` implements, for [`World::implementations`]
/// ([`decided`]).
fn implemented(resolver: &TraitResolver<'_>, src: &Src, block: &ImplRecord) -> BTreeSet<TraitId> {
    decided(resolver.implemented_checked(src.package, block), || {
        format!(
            "the trait `{}` of {}'s `impl` block for `{}`",
            block.trait_path().unwrap_or_default().join("::"),
            src.package,
            block.type_owner()
        )
    })
}

/// Words that open a parenthesis without calling anything.
const KEYWORDS: [&str; 22] = [
    "if", "while", "match", "return", "in", "as", "for", "loop", "move", "else", "let", "mut",
    "ref", "unsafe", "async", "await", "where", "impl", "dyn", "fn", "break", "continue",
];

impl World {
    fn new() -> Self {
        Self::of(product())
    }

    /// The world of `product`'s packages, each reaching itself and its product dependencies.
    fn of(product: Product) -> Self {
        let Product {
            packages,
            mut features,
        } = product;
        let srcs: Vec<Src> = packages
            .iter()
            .map(|(name, _)| {
                let package: &'static str = Box::leak(name.clone().into_boxed_str());
                Src {
                    package,
                    index: Index::of_package(package),
                    features: Box::leak(Box::new(features.remove(name).unwrap_or_default())),
                }
            })
            .collect();
        let direct: Vec<BTreeSet<usize>> = packages
            .iter()
            .map(|(_, dependencies)| {
                dependencies
                    .iter()
                    .map(|name| {
                        srcs.iter()
                            .position(|src| src.package == name)
                            .expect("a product package's dependency is a product package")
                    })
                    .collect()
            })
            .collect();
        Self::over(srcs, &direct)
    }

    /// The world of `srcs`, each reaching itself and its `direct` first-party product
    /// dependencies, and every package one of those re-exports.
    fn over(srcs: Vec<Src>, direct: &[BTreeSet<usize>]) -> Self {
        let re_exports: Vec<BTreeSet<usize>> = srcs
            .iter()
            .enumerate()
            .map(|(at, src)| re_exported_by(src, &direct[at], &srcs))
            .collect();
        let reach = (0..srcs.len())
            .map(|at| {
                let mut reach = direct[at].clone();
                reach.insert(at);
                // A re-export of a re-export is a name too: grow to a fixed point.
                loop {
                    let more: BTreeSet<usize> = reach
                        .iter()
                        .filter(|&&other| other != at)
                        .flat_map(|&other| re_exports[other].iter().copied())
                        .filter(|package| !reach.contains(package))
                        .collect();
                    if more.is_empty() {
                        break reach;
                    }
                    reach.extend(more);
                }
            })
            .collect();
        let mut callables: HashMap<String, Vec<Callable>> = HashMap::new();
        let mut fields: HashMap<(String, String), Vec<(usize, &'static ItemRecord)>> =
            HashMap::new();
        let mut deref_types = BTreeSet::new();
        let resolver = TraitResolver::new(
            &srcs
                .iter()
                .map(|src| (src.package, src.index))
                .collect::<Vec<_>>(),
        );
        let mut declared: BTreeMap<TraitId, Vec<(usize, &'static ItemRecord)>> = BTreeMap::new();
        let mut implementations: BTreeMap<TraitId, Vec<Implementation>> = BTreeMap::new();
        for (at, src) in srcs.iter().enumerate() {
            for block in src.index.impls() {
                if src.in_product(block.whole().start())
                    && block.trait_name().is_some_and(|name| {
                        name.rsplit("::")
                            .next()
                            .is_some_and(|last| last.trim() == "Deref")
                    })
                {
                    deref_types.insert(block.type_owner().to_owned());
                }
                if !src.in_product(block.whole().start()) {
                    continue;
                }
                for id in implemented(&resolver, src, block) {
                    let methods = src
                        .index
                        .items()
                        .iter()
                        .filter(|record| {
                            record.kind().is_callable()
                                && block.body().holds(record.whole().start())
                                && src.product_item(record)
                        })
                        .collect();
                    implementations.entry(id).or_default().push(Implementation {
                        src: at,
                        block,
                        methods,
                    });
                }
            }
            for declaration in src.index.traits() {
                let methods: Vec<(usize, &'static ItemRecord)> = src
                    .index
                    .items()
                    .iter()
                    .filter(|record| {
                        record.kind().is_callable()
                            && record.type_owner().is_none()
                            && declaration.body().holds(record.whole().start())
                    })
                    .map(|record| (at, record))
                    .collect();
                for id in resolver.identities(src.package, declaration) {
                    declared
                        .entry(id)
                        .or_default()
                        .extend(methods.iter().copied());
                }
            }
            for record in src.index.items() {
                if record.kind() == ItemKind::Field
                    && let Some(owner) = record.type_owner()
                    && (src.product_item(record) || owner == "ReceiverTypingSourceShapes")
                {
                    fields
                        .entry((owner.to_owned(), record.name().to_owned()))
                        .or_default()
                        .push((at, record));
                }
                if !src.product_item(record) {
                    continue;
                }
                if record.kind().is_callable() {
                    callables
                        .entry(record.name().to_owned())
                        .or_default()
                        .push(Callable {
                            src: at,
                            module: record.module_paths()[0].to_owned(),
                            type_owner: record.type_owner().map(ToOwned::to_owned),
                            trait_name: record.trait_name().map(ToOwned::to_owned),
                            record: Some(record),
                        });
                }
            }
            // `#[from]` on an error enum's field makes a first-party `From::from` no byte holds.
            for attribute in attributes(src) {
                if path_of(src, &attribute.body).0 != "from" || !src.in_product(attribute.start) {
                    continue;
                }
                if let Some(owner) = src
                    .index
                    .items()
                    .iter()
                    .filter(|r| r.kind() == ItemKind::Enum && r.whole().holds(attribute.start))
                    .min_by_key(|r| r.whole().len())
                {
                    callables
                        .entry("from".to_owned())
                        .or_default()
                        .push(Callable {
                            src: at,
                            module: owner.module_paths()[0].to_owned(),
                            type_owner: Some(owner.name().to_owned()),
                            trait_name: Some("From".to_owned()),
                            record: None,
                        });
                }
            }
        }
        let graph = call_graph(&srcs);
        let from_impls = callables
            .get("from")
            .into_iter()
            .flatten()
            .filter(|callable| {
                callable
                    .trait_name
                    .as_deref()
                    .is_some_and(|name| name == "From" || name.starts_with("From<"))
            })
            .filter_map(|callable| {
                callable
                    .record
                    .and_then(|record| graph.id_of(srcs[callable.src].package, record))
            })
            .collect();
        Self {
            srcs,
            reach,
            callables,
            fields,
            deref_types,
            resolver,
            declared,
            implementations,
            graph,
            from_impls,
        }
    }

    fn src(&self, package: &str) -> &Src {
        self.srcs
            .iter()
            .find(|src| src.package == package)
            .expect("a product package")
    }

    /// The key a callable is named by in the tables: an item's, or a generated one's.
    fn key(&self, callable: &Callable) -> String {
        let src = &self.srcs[callable.src];
        match callable.record {
            Some(record) => key_of(src, record),
            None => format!(
                "{} {}::{}::from (generated)",
                src.package,
                callable.module,
                callable.type_owner.as_deref().unwrap_or_default()
            ),
        }
    }

    /// The one first-party type a written type spells. Only leading references are peeled; the
    /// rest must be one path with no arguments or other type syntax, and that path's final name
    /// must identify exactly one reachable first-party type.
    fn written_type(&self, from: usize, src: &Src, toks: &[Tok]) -> BTreeSet<String> {
        let mut at = 0;
        while src.is(toks.get(at), "&") {
            at += 1;
            if toks.get(at).is_some_and(|tok| tok.kind == Kind::Lifetime) {
                at += 1;
            }
            if src.is(toks.get(at), "mut") {
                at += 1;
            }
        }
        let path = &toks[at..];
        if path.is_empty()
            || path.iter().enumerate().any(|(at, tok)| {
                if at % 2 == 0 {
                    tok.kind != Kind::Ident
                } else {
                    !src.is(Some(tok), "::")
                }
            })
            || path.len().is_multiple_of(2)
        {
            return BTreeSet::new();
        }
        let name = src.text(*path.last().expect("a nonempty path"));
        if self.reachable_type_locations(from, name).len() == 1 {
            BTreeSet::from([name.to_owned()])
        } else {
            BTreeSet::new()
        }
    }

    fn reachable_type_locations(&self, from: usize, name: &str) -> BTreeSet<(usize, String)> {
        self.reach[from]
            .iter()
            .flat_map(|at| {
                self.srcs[*at]
                    .index
                    .items()
                    .iter()
                    .filter(|record| {
                        record.kind().is_type()
                            && record.name() == name
                            && self.srcs[*at].product_item(record)
                    })
                    .map(|record| (*at, record.module_paths()[0].to_owned()))
            })
            .collect()
    }

    fn receiver_type_must_fallback(
        &self,
        from: usize,
        name: &str,
        types: &BTreeSet<String>,
    ) -> bool {
        if types.iter().any(|ty| self.deref_types.contains(ty)) {
            return true;
        }
        self.callables
            .get(name)
            .into_iter()
            .flatten()
            .filter(|callable| {
                self.reach[from].contains(&callable.src)
                    && callable
                        .type_owner
                        .as_ref()
                        .is_some_and(|owner| types.contains(owner))
            })
            .filter_map(|callable| callable.trait_name.as_deref())
            .any(|trait_name| {
                let bare = trait_name
                    .split('<')
                    .next()
                    .unwrap_or(trait_name)
                    .rsplit("::")
                    .next()
                    .unwrap_or(trait_name)
                    .trim();
                self.callables.values().flatten().any(|candidate| {
                    self.reach[from].contains(&candidate.src)
                        && candidate.type_owner.is_none()
                        && candidate.trait_name.as_deref().is_some_and(|name| {
                            name.split('<')
                                .next()
                                .unwrap_or(name)
                                .rsplit("::")
                                .next()
                                .unwrap_or(name)
                                .trim()
                                == bare
                        })
                })
            })
    }
}

impl World {
    /// The first-party supertraits of `id`, each resolved where it is declared — refused by name
    /// when one chains past the resolver's hop limit ([`decided`]).
    fn supertraits(&self, id: &TraitId) -> BTreeSet<TraitId> {
        decided(self.resolver.supertraits_checked(id), || {
            format!("a supertrait of `{id}`")
        })
    }

    /// **The first-party methods a call of `method` on a value known only by the traits `stated`
    /// can run** — `None` when no first-party trait among them, or among their supertraits,
    /// declares `method` (a method of a standard or third-party trait, or of a foreign
    /// supertrait), which leaves the call to the untyped reading.
    ///
    /// The traits are identities ([`TraitId`]): two traits of one name in two modules are two.
    /// The supertraits are followed to a fixed point, each resolved where it is declared. For each
    /// trait of them that declares `method`, the answer is the `method` of each product `impl` of
    /// it — for a supertrait, only the impls for a type that implements a stated trait — on every
    /// arm the records carry (a `cfg(target_os)` impl is an implementation like any other); and
    /// the trait's default `method`, with its body, when one of those impls does not override it
    /// or when there is none.
    fn trait_methods(
        &self,
        stated: &BTreeSet<TraitId>,
        method: &str,
    ) -> Option<Vec<(usize, &'static ItemRecord)>> {
        let mut closure = stated.clone();
        let mut work: Vec<TraitId> = stated.iter().cloned().collect();
        while let Some(id) = work.pop() {
            for supertrait in self.supertraits(&id) {
                if closure.insert(supertrait.clone()) {
                    work.push(supertrait);
                }
            }
        }
        let declaring: Vec<&TraitId> = closure
            .iter()
            .filter(|id| {
                self.declared.get(*id).is_some_and(|methods| {
                    methods.iter().any(|(_, record)| record.name() == method)
                })
            })
            .collect();
        if declaring.is_empty() {
            return None;
        }
        let implementors: BTreeSet<&str> = stated
            .iter()
            .flat_map(|id| self.implementations.get(id).into_iter().flatten())
            .map(|implementation| implementation.block.type_owner())
            .collect();
        let mut out: Vec<(usize, &'static ItemRecord)> = Vec::new();
        for id in declaring {
            let blocks: Vec<&Implementation> = self
                .implementations
                .get(id)
                .into_iter()
                .flatten()
                .filter(|implementation| {
                    stated.contains(id) || implementors.contains(implementation.block.type_owner())
                })
                .collect();
            let mut default_runs = blocks.is_empty();
            for implementation in blocks {
                let overrides: Vec<&'static ItemRecord> = implementation
                    .methods
                    .iter()
                    .copied()
                    .filter(|record| record.name() == method)
                    .collect();
                default_runs |= overrides.is_empty();
                out.extend(
                    overrides
                        .into_iter()
                        .map(|record| (implementation.src, record)),
                );
            }
            if default_runs {
                out.extend(
                    self.declared[id]
                        .iter()
                        .copied()
                        .filter(|(_, record)| record.name() == method && record.body().is_some()),
                );
            }
        }
        let mut seen = BTreeSet::new();
        out.retain(|(src, record)| seen.insert((*src, record.whole().start())));
        Some(out)
    }
}

/// The index of the `>` closing the `<` at `toks[open]`.
fn angle_close(src: &Src, toks: &[Tok], open: usize) -> Option<usize> {
    let mut depth = 0usize;
    for (at, tok) in toks.iter().enumerate().skip(open) {
        if tok.kind != Kind::Punct {
            continue;
        }
        match src.text(*tok) {
            "<" => depth += 1,
            ">" => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(at);
                }
            }
            _ => {}
        }
    }
    None
}

/// The traits a bound list names, each as the path it is written as, without arguments:
/// `Driver + Send + 'static` names `Driver` and `Send`, `for<'a> crate::lane::Owed<Id>` names
/// `crate::lane::Owed`; a lifetime and a relaxed `?Sized` name nothing.
fn bound_traits(src: &Src, toks: &[Tok]) -> Vec<Vec<&'static str>> {
    let mut bounds: Vec<&[Tok]> = Vec::new();
    let mut depth = 0usize;
    let mut start = 0;
    for (at, tok) in toks.iter().enumerate() {
        if tok.kind != Kind::Punct {
            continue;
        }
        match src.text(*tok) {
            "(" | "[" | "{" | "<" => depth += 1,
            ")" | "]" | "}" | ">" => depth = depth.saturating_sub(1),
            "+" if depth == 0 => {
                bounds.push(&toks[start..at]);
                start = at + 1;
            }
            _ => {}
        }
    }
    bounds.push(&toks[start..]);
    bounds
        .into_iter()
        .filter_map(|mut bound| {
            if src.is(bound.first(), "?") {
                return None;
            }
            if src.is(bound.first(), "for") && src.is(bound.get(1), "<") {
                bound = &bound[angle_close(src, bound, 1)? + 1..];
            }
            let mut at = usize::from(src.is(bound.first(), "::"));
            let mut path = Vec::new();
            while let Some(segment) = bound.get(at).filter(|tok| tok.kind == Kind::Ident) {
                path.push(src.text(*segment));
                if !src.is(bound.get(at + 1), "::") {
                    break;
                }
                at += 2;
            }
            (!path.is_empty()).then_some(path)
        })
        .collect()
}

/// Adds to `into` the bounds a header states on the generic parameters it declares: those of the
/// `<…>` list following `toks[after]` (each parameter's own, a default left out) and those its
/// `where` clause puts on a parameter already in `into`. A lifetime or a `const` parameter states
/// no trait.
fn header_bounds(
    src: &Src,
    toks: &[Tok],
    after: usize,
    into: &mut HashMap<&'static str, Vec<Vec<&'static str>>>,
) {
    if src.is(toks.get(after + 1), "<")
        && let Some(close) = angle_close(src, toks, after + 1)
    {
        for param in split_commas(src, &toks[after + 2..close]) {
            let Some(first) = param.first() else {
                continue;
            };
            if first.kind != Kind::Ident || src.is(Some(first), "const") {
                continue;
            }
            let bounds = into.entry(src.text(*first)).or_default();
            if src.is(param.get(1), ":") {
                let end = param
                    .iter()
                    .position(|tok| src.is(Some(tok), "="))
                    .unwrap_or(param.len());
                bounds.extend(bound_traits(src, &param[2..end]));
            }
        }
    }
    if let Some(clause) = toks.iter().position(|tok| src.is(Some(tok), "where")) {
        for predicate in split_commas(src, &toks[clause + 1..]) {
            if let [name, colon, rest @ ..] = predicate.as_slice()
                && src.is(Some(colon), ":")
                && let Some(bounds) = into.get_mut(src.text(*name))
            {
                bounds.extend(bound_traits(src, rest));
            }
        }
    }
}

/// **The traits a written type states its value is known by**: `dyn A + B` and `impl A` name
/// their bounds (each resolved by `resolve`), behind any `&`, `&mut`, lifetime, `Box<…>`, `Arc<…>`
/// or `Rc<…>`, and a generic parameter of `generics` names its bounds. `None` for every other type
/// — a concrete type states no trait, and an alias is not resolved. A standard or third-party
/// bound resolves to no trait, so `dyn std::io::Write` states an empty set.
fn stated_traits(
    src: &Src,
    toks: &[Tok],
    generics: &HashMap<&'static str, BTreeSet<TraitId>>,
    resolve: &dyn Fn(&[&str]) -> BTreeSet<TraitId>,
) -> Option<BTreeSet<TraitId>> {
    let mut at = 0;
    while src.is(toks.get(at), "&") {
        at += 1;
        if toks.get(at).is_some_and(|tok| tok.kind == Kind::Lifetime) {
            at += 1;
        }
        if src.is(toks.get(at), "mut") {
            at += 1;
        }
    }
    let toks = &toks[at..];
    if src.is(toks.first(), "dyn") || src.is(toks.first(), "impl") {
        return Some(
            bound_traits(src, &toks[1..])
                .iter()
                .flat_map(|path| resolve(path))
                .collect(),
        );
    }
    let Some(open) = toks.iter().position(|tok| src.is(Some(tok), "<")) else {
        let [name] = toks else {
            return None;
        };
        return generics.get(src.text(*name)).cloned();
    };
    let path = &toks[..open];
    let is_path = path.len() % 2 == 1
        && path.iter().enumerate().all(|(at, tok)| {
            if at % 2 == 0 {
                tok.kind == Kind::Ident
            } else {
                src.is(Some(tok), "::")
            }
        });
    if !is_path
        || !["Box", "Arc", "Rc"].contains(&src.text(path[open - 1]))
        || angle_close(src, toks, open)? + 1 != toks.len()
    {
        return None;
    }
    let [inner]: [Vec<Tok>; 1] = split_commas(src, &toks[open + 1..toks.len() - 1])
        .try_into()
        .ok()?;
    stated_traits(src, &inner, generics, resolve)
}

/// One call, or one macro invocation, found in a body.
#[derive(Clone, Debug)]
struct Site {
    at: usize,
    name: &'static str,
    form: Form,
}

#[derive(Clone, Debug)]
enum Form {
    /// `receiver.name(…)`: the receiver as a chain of names, when it is one.
    Method(Option<Vec<&'static str>>),
    /// `a::b::name(…)`: the qualifiers.
    Path(Vec<&'static str>),
    /// `name(…)`.
    Bare,
    /// `name!(…)`.
    Macro,
    /// A function handed by value to the admission as its work: `admitted::<…>(name)`.
    Value,
}

/// A function's body, as the resolver reads it: its tokens, and what its parameters are.
struct Body<'w> {
    world: &'w World,
    src: usize,
    record: &'static ItemRecord,
    params: HashMap<&'static str, Vec<Tok>>,
    /// Simple locals whose current type is stated by one unshadowed, unreassigned binding.
    locals: HashMap<&'static str, (usize, BTreeSet<String>)>,
    /// The same bindings with the type each one writes ([`annotated_lets`]), whatever it is.
    annotated: HashMap<&'static str, (usize, Vec<Tok>)>,
    /// The bounds on the generic parameters the body can name ([`Body::generic_bounds`]), read
    /// the first time a call asks.
    generics: std::cell::OnceCell<HashMap<&'static str, BTreeSet<TraitId>>>,
    /// The lexical scopes of the body's bindings ([`binding_scopes`]), read the first time a
    /// call on a parameter asks.
    scopes: std::cell::OnceCell<Option<Vec<BindingScope>>>,
    toks: Vec<Tok>,
}

impl<'w> Body<'w> {
    fn new(world: &'w World, src: usize, record: &'static ItemRecord) -> Self {
        let s = &world.srcs[src];
        let declaration = s.lex(record.declaration().start(), record.declaration().end());
        let mut params = HashMap::new();
        let open = declaration
            .iter()
            .position(|t| s.is(Some(t), "fn"))
            .and_then(|at| {
                declaration[at..]
                    .iter()
                    .position(|t| s.is(Some(t), "("))
                    .map(|open| open + at)
            });
        if let Some(open) = open
            && let Some(close) = closing(s, &declaration, open)
        {
            for param in split_commas(s, &declaration[open + 1..close]) {
                let Some(colon) = param.iter().position(|t| s.is(Some(t), ":")) else {
                    continue;
                };
                for name in pattern_names(s, &param[..colon]) {
                    params.insert(name, param[colon + 1..].to_vec());
                }
            }
        }
        let toks = record
            .body()
            .map_or_else(Vec::new, |body| s.lex(body.start(), body.end()));
        let annotated = annotated_lets(s, &toks, &params);
        let locals = local_types(world, src, &annotated);
        Self {
            world,
            src,
            record,
            params,
            locals,
            annotated,
            generics: std::cell::OnceCell::new(),
            scopes: std::cell::OnceCell::new(),
            toks,
        }
    }

    fn s(&self) -> &Src {
        &self.world.srcs[self.src]
    }

    /// Every call and macro invocation in the body, in the order they are written.
    fn sites(&self) -> Vec<Site> {
        sites_of(self.s(), &self.toks)
    }

    fn own_methods(&self, all: &[Callable]) -> Vec<Callable> {
        let own = self
            .record
            .type_owner()
            .map(|owner| BTreeSet::from([owner.to_owned()]))
            .unwrap_or_default();
        let methods = methods_of(all, &own);
        let module = self.record.module_paths()[0];
        let here: Vec<Callable> = methods
            .iter()
            .filter(|c| c.src == self.src && c.module == module)
            .cloned()
            .collect();
        if here.is_empty() { methods } else { here }
    }

    fn self_field_type(&self, field: &str) -> BTreeSet<String> {
        let Some(owner) = self.record.type_owner() else {
            return BTreeSet::new();
        };
        let module = self.record.module_paths()[0];
        let mut types = BTreeSet::new();
        for (at, record) in self
            .world
            .fields
            .get(&(owner.to_owned(), field.to_owned()))
            .into_iter()
            .flatten()
            .filter(|(at, record)| *at == self.src && record.module_paths()[0] == module)
        {
            let src = &self.world.srcs[*at];
            let toks = src.lex(record.whole().start(), record.whole().end());
            if let Some(colon) = toks.iter().position(|tok| src.is(Some(tok), ":")) {
                types.extend(self.world.written_type(self.src, src, &toks[colon + 1..]));
            }
        }
        types
    }

    fn receiver_types(&self, site: &Site) -> Option<BTreeSet<String>> {
        let Form::Method(Some(chain)) = &site.form else {
            return None;
        };
        let types = match chain.as_slice() {
            ["self", field] => self.self_field_type(field),
            [local] => self
                .locals
                .get(local)
                .filter(|(bound, _)| *bound < site.at)
                .map(|(_, types)| types.clone())
                .unwrap_or_default(),
            _ => BTreeSet::new(),
        };
        if types.is_empty()
            || self
                .world
                .receiver_type_must_fallback(self.src, site.name, &types)
        {
            None
        } else {
            Some(types)
        }
    }

    fn receiver_is_typed(&self, site: &Site) -> bool {
        match &site.form {
            Form::Method(_) => self.receiver_types(site).is_some(),
            _ => true,
        }
    }

    /// **The traits a call's receiver is stated to be known by** ([`stated_traits`]), by their
    /// identities; `None` when the source states none. The receiver is read where the source
    /// writes its type: a parameter no other binding in scope at the call shadows
    /// ([`shadowed_at`]), a
    /// local of [`annotated_lets`] bound before the call, `self.field` by every declaration of the
    /// field (all of them must state a trait), and `self` in a trait's default method, which is
    /// the trait. A path call's qualifier states its traits when it is a generic parameter, `Self`
    /// in a trait's default method, or a path that resolves to a first-party trait
    /// (`Driver::prepare`, `crate::update_job::Driver::prepare`).
    fn receiver_traits(&self, site: &Site) -> Option<BTreeSet<TraitId>> {
        let s = self.s();
        let generics = self.generics.get_or_init(|| self.generic_bounds());
        let resolve = |path: &[&str]| self.traits_named(path);
        match &site.form {
            Form::Method(Some(chain)) => match chain.as_slice() {
                ["self"] => generics.get("Self").cloned(),
                [name] => match self.params.get(name) {
                    Some(written) => {
                        let scopes = self
                            .scopes
                            .get_or_init(|| scope_body(s, self.record).and_then(binding_scopes));
                        (!shadowed_at(scopes.as_deref(), name, site.at))
                            .then(|| stated_traits(s, written, generics, &resolve))
                            .flatten()
                    }
                    None => self
                        .annotated
                        .get(name)
                        .filter(|(bound, _)| *bound < site.at)
                        .and_then(|(_, written)| stated_traits(s, written, generics, &resolve)),
                },
                ["self", field] => {
                    let declared = self.self_field_written(field);
                    if declared.is_empty() {
                        return None;
                    }
                    let mut traits = BTreeSet::new();
                    for written in declared {
                        traits.extend(stated_traits(s, &written, generics, &resolve)?);
                    }
                    Some(traits)
                }
                _ => None,
            },
            Form::Path(quals) => {
                if let [qualifier] = quals.as_slice()
                    && let Some(bounds) = generics.get(qualifier)
                {
                    return Some(bounds.clone());
                }
                let named = self.traits_named(quals);
                (!named.is_empty()).then_some(named)
            }
            _ => None,
        }
    }

    /// The first-party traits a path written in this body names, in each module the body is
    /// declared in.
    fn traits_named(&self, path: &[&str]) -> BTreeSet<TraitId> {
        let path: Vec<String> = path.iter().map(|segment| (*segment).to_owned()).collect();
        let package = self.s().package;
        self.record
            .module_paths()
            .into_iter()
            .flat_map(|module| {
                decided(
                    self.world.resolver.resolve_checked(package, module, &path),
                    || format!("the trait path `{}` in {package} {module}", path.join("::")),
                )
            })
            .collect()
    }

    /// The type each declaration of `self.field` writes, read as [`Body::self_field_type`] reads
    /// the field: the owner's fields of that name in this body's package and module.
    fn self_field_written(&self, field: &str) -> Vec<Vec<Tok>> {
        let Some(owner) = self.record.type_owner() else {
            return Vec::new();
        };
        let module = self.record.module_paths()[0];
        self.world
            .fields
            .get(&(owner.to_owned(), field.to_owned()))
            .into_iter()
            .flatten()
            .filter(|(at, record)| *at == self.src && record.module_paths()[0] == module)
            .filter_map(|(at, record)| {
                let src = &self.world.srcs[*at];
                let toks = src.lex(record.whole().start(), record.whole().end());
                let colon = toks.iter().position(|tok| src.is(Some(tok), ":"))?;
                Some(toks[colon + 1..].to_vec())
            })
            .collect()
    }

    /// The traits bounding every generic parameter the body can name, by parameter: its `impl`
    /// block's, its own, and — in a trait's default method — its trait's, where `Self` is the
    /// trait. Each bound is resolved in the body's module.
    fn generic_bounds(&self) -> HashMap<&'static str, BTreeSet<TraitId>> {
        let s = self.s();
        let start = self.record.whole().start();
        let mut written: HashMap<&'static str, Vec<Vec<&'static str>>> = HashMap::new();
        if let Some(block) = s
            .index
            .impls()
            .iter()
            .filter(|block| block.body().holds(start))
            .min_by_key(|block| block.body().len())
        {
            let toks = s.lex(block.whole().start(), block.body().start());
            if let Some(at) = toks.iter().position(|tok| s.is(Some(tok), "impl")) {
                header_bounds(s, &toks, at, &mut written);
            }
        }
        let mut bounds: HashMap<&'static str, BTreeSet<TraitId>> = HashMap::new();
        if self.record.type_owner().is_none()
            && let Some(declaration) = s
                .index
                .traits()
                .iter()
                .filter(|declaration| declaration.body().holds(start))
                .min_by_key(|declaration| declaration.body().len())
        {
            bounds.insert(
                "Self",
                self.world.resolver.identities(s.package, declaration),
            );
            let toks = s.lex(declaration.whole().start(), declaration.body().start());
            if let Some(at) = toks.iter().position(|tok| s.is(Some(tok), "trait")) {
                header_bounds(s, &toks, at + 1, &mut written);
            }
        }
        let declaration = s.lex(
            self.record.declaration().start(),
            self.record.declaration().end(),
        );
        if let Some(at) = declaration.iter().position(|tok| s.is(Some(tok), "fn")) {
            header_bounds(s, &declaration, at + 1, &mut written);
        }
        for (name, paths) in written {
            bounds
                .entry(name)
                .or_default()
                .extend(paths.iter().flat_map(|path| self.traits_named(path)));
        }
        bounds
    }

    /// The first-party items a call can be, by what the source states. A receiver type exists only
    /// for `self.field` whose declaration is a reference or one unambiguous first-party path, and
    /// for `let name: Type = …` with the same type restriction when `name` has exactly one binding
    /// in the whole function and is never assigned. Constructor and return expressions are never
    /// typed. A same-name type ambiguity, trait-provided method, or `Deref` receiver is untyped.
    /// Every narrowed lookup goes through [`nonempty_or`], so an empty typed answer always returns
    /// the name-matched answer.
    fn resolve(&self, site: &Site) -> Vec<Callable> {
        let world = self.world;
        let reach = &world.reach[self.src];
        let named = |name: &str| -> Vec<Callable> {
            world
                .callables
                .get(name)
                .into_iter()
                .flatten()
                .filter(|c| reach.contains(&c.src))
                .cloned()
                .collect()
        };
        let all = named(site.name);
        let free = |filter: &dyn Fn(&Callable) -> bool| -> Vec<Callable> {
            all.iter()
                .filter(|c| c.type_owner.is_none() && c.trait_name.is_none() && filter(c))
                .cloned()
                .collect()
        };
        let any_method = || -> Vec<Callable> {
            all.iter()
                .filter(|c| c.type_owner.is_some())
                .cloned()
                .collect()
        };
        let (fallback, preferred) = match &site.form {
            Form::Macro => (Vec::new(), Vec::new()),
            Form::Method(_) if site.name == "into" => {
                let from: Vec<Callable> = named("from")
                    .into_iter()
                    .filter(|c| {
                        c.trait_name
                            .as_deref()
                            .is_some_and(|t| t == "From" || t.starts_with("From<"))
                    })
                    .collect();
                (from.clone(), from)
            }
            Form::Method(Some(chain)) if chain.as_slice() == ["self"] => {
                let preferred = self
                    .record
                    .type_owner()
                    .filter(|owner| !world.deref_types.contains(*owner))
                    .map_or_else(Vec::new, |_| self.own_methods(&all));
                (any_method(), preferred)
            }
            Form::Method(Some(_)) => {
                let preferred = self
                    .receiver_types(site)
                    .map_or_else(Vec::new, |types| methods_of(&all, &types));
                (any_method(), preferred)
            }
            Form::Method(None) => (any_method(), any_method()),
            Form::Path(quals) => match quals.last().copied().unwrap_or_default() {
                "Self" => (any_method(), self.own_methods(&all)),
                "crate" | "self" | "super" => {
                    let preferred = free(&|c: &Callable| c.src == self.src);
                    (free(&|_| true), preferred)
                }
                qualifier if qualifier.starts_with(|c: char| c.is_ascii_uppercase()) => (
                    any_method(),
                    methods_of(&all, &BTreeSet::from([qualifier.to_owned()])),
                ),
                module => {
                    let preferred =
                        free(&|c: &Callable| c.module.rsplit("::").next() == Some(module));
                    (free(&|_| true), preferred)
                }
            },
            Form::Bare | Form::Value => {
                if self.params.contains_key(site.name) {
                    (Vec::new(), Vec::new())
                } else {
                    let module = self.record.module_paths()[0];
                    let here = free(&|c: &Callable| c.src == self.src && c.module == module);
                    let package = free(&|c: &Callable| c.src == self.src);
                    let preferred = if !here.is_empty() { here } else { package };
                    (free(&|_| true), preferred)
                }
            }
        };
        nonempty_or(fallback, preferred)
    }
}

fn nonempty_or(fallback: Vec<Callable>, preferred: Vec<Callable>) -> Vec<Callable> {
    if preferred.is_empty() {
        fallback
    } else {
        preferred
    }
}

/// The end of a `let` statement, respecting delimiters inside its initializer.
fn let_end(s: &Src, toks: &[Tok], start: usize) -> usize {
    let mut depth = 0usize;
    for (at, tok) in toks.iter().enumerate().skip(start) {
        match s.text(*tok) {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" if depth > 0 => depth -= 1,
            ";" if depth == 0 => return at,
            _ => {}
        }
    }
    toks.len()
}

fn top_level_token(s: &Src, toks: &[Tok], wanted: &str) -> Option<usize> {
    let mut depth = 0usize;
    for (at, tok) in toks.iter().enumerate() {
        match s.text(*tok) {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" if depth > 0 => depth -= 1,
            text if depth == 0 && text == wanted => return Some(at),
            _ => {}
        }
    }
    None
}

fn receiver_pattern_names(src: &Src, toks: &[Tok]) -> BTreeSet<&'static str> {
    toks.iter()
        .filter(|tok| tok.kind == Kind::Ident)
        .map(|tok| src.text(*tok))
        .filter(|name| {
            ![
                "let", "mut", "ref", "Some", "Ok", "Err", "None", "self", "Self",
            ]
            .contains(name)
                && !name.starts_with(|c: char| c.is_ascii_uppercase())
        })
        .collect()
}

/// How often `name` is introduced by any binding form this lexical guard can encounter. A
/// conservative extra count only disables typing, which is the required direction when a pattern
/// cannot be decided mechanically.
fn binding_count(src: &Src, toks: &[Tok], params: &HashMap<&str, Vec<Tok>>, name: &str) -> usize {
    let mut count = usize::from(params.contains_key(name));
    for (at, tok) in toks.iter().enumerate() {
        if src.is(Some(tok), "let") {
            let end = let_end(src, toks, at + 1);
            let statement = &toks[at + 1..end];
            let pattern_end = top_level_token(src, statement, "=").unwrap_or(statement.len());
            count +=
                usize::from(receiver_pattern_names(src, &statement[..pattern_end]).contains(name));
        }
        if src.is(Some(tok), "for") {
            let rest = &toks[at + 1..];
            if let Some(end) = top_level_token(src, rest, "in") {
                count += usize::from(receiver_pattern_names(src, &rest[..end]).contains(name));
            }
        }
        if src.is(Some(tok), "match") {
            let open = depth_zero(src, toks, at + 1, &["{"]);
            let Some(close) = (open < toks.len())
                .then(|| closing(src, toks, open))
                .flatten()
            else {
                continue;
            };
            let arms = &toks[open + 1..close];
            let mut arm = 0;
            while arm < arms.len() {
                let arrow = depth_zero(src, arms, arm, &["=>"]);
                if arrow >= arms.len() {
                    break;
                }
                let guard = arms[arm..arrow]
                    .iter()
                    .position(|tok| src.is(Some(tok), "if"))
                    .map_or(arrow, |guard| arm + guard);
                count += usize::from(receiver_pattern_names(src, &arms[arm..guard]).contains(name));
                let body = arrow + 1;
                arm = if src.is(arms.get(body), "{") {
                    closing(src, arms, body).map_or(arms.len(), |close| close + 1)
                } else {
                    depth_zero(src, arms, body, &[","])
                };
                if src.is(arms.get(arm), ",") {
                    arm += 1;
                }
            }
        }
    }
    let mut at = 0;
    while at < toks.len() {
        if let Some(close) = closure_parameters(src, toks, at) {
            count += usize::from(receiver_pattern_names(src, &toks[at + 1..close]).contains(name));
            at = close + 1;
        } else {
            at += 1;
        }
    }
    count
}

/// Words after which a `|` opens a closure's parameters rather than continuing an operand.
const CLOSURE_LEADS: [&str; 6] = ["move", "return", "in", "else", "break", "async"];

/// When `toks[at]` is the `|` opening a closure's parameters, the index of the `|` closing them.
///
/// A `|` that follows an operand — a name, a literal, `)`, `]`, `}` or `?` — is a match or-pattern's
/// bar (`Some(0) | None =>`, `if let A | B = …`) or a bitwise or, never a closure: a closure stands
/// where an expression starts (after `(`, `,`, `=`, `{`, `;`, `=>`, an operator, or `move`). Its
/// parameters end at the next `|` outside any bracket.
fn closure_parameters(src: &Src, toks: &[Tok], at: usize) -> Option<usize> {
    if !src.is(toks.get(at), "|") {
        return None;
    }
    if let Some(before) = at.checked_sub(1).map(|before| toks[before]) {
        let operand = match before.kind {
            Kind::Literal | Kind::Lifetime => true,
            Kind::Ident => !CLOSURE_LEADS.contains(&src.text(before)),
            Kind::Punct => [")", "]", "}", "?"].contains(&src.text(before)),
        };
        if operand {
            return None;
        }
    }
    let mut depth = 0usize;
    for (inner, tok) in toks.iter().enumerate().skip(at + 1) {
        if tok.kind != Kind::Punct {
            continue;
        }
        match src.text(*tok) {
            "(" | "[" | "{" => depth += 1,
            ")" | "]" | "}" => depth = depth.checked_sub(1)?,
            "|" if depth == 0 => return Some(inner),
            _ => {}
        }
    }
    None
}

/// One binding a function body introduces: the name, and the `[from, to)` union offsets of its
/// lexical scope.
type BindingScope = (String, usize, usize);

/// The text and union base of one body whose binding scopes are to be read.
struct ScopeBody<'a> {
    text: &'a str,
    base: usize,
}

fn scope_body<'a>(src: &'a Src, record: &ItemRecord) -> Option<ScopeBody<'a>> {
    let body = record.body()?;
    Some(ScopeBody {
        text: src.index.text(body),
        base: body.start(),
    })
}

/// **The lexical scope of every binding a function body introduces**, read with `syn` from the
/// body's text (the bytes `bt-source`'s item record spans — the source `bt-source` itself lowers
/// with `syn`), as union offsets: a `let` from the end of its statement to the end of its
/// enclosing block; a let-chain binding from the end of its own `let` through the later operands
/// and branch, loop or match-arm body; a `for` pattern over the loop body; a match arm's pattern
/// over the arm (its guard included); a closure's parameters over its body. Macro invocations are
/// opaque tokens to `syn` and introduce no binding. `None` when the body does not parse.
fn binding_scopes(body: ScopeBody<'_>) -> Option<Vec<BindingScope>> {
    let block = syn::parse_str::<syn::Block>(body.text).ok()?;
    let mut reader = ScopeReader {
        base: body.base,
        scopes: Vec::new(),
    };
    syn::visit::Visit::visit_block(&mut reader, &block);
    Some(reader.scopes)
}

/// The walk of [`binding_scopes`].
struct ScopeReader {
    base: usize,
    scopes: Vec<BindingScope>,
}

impl ScopeReader {
    fn start(&self, node: &impl syn::spanned::Spanned) -> usize {
        self.base + node.span().byte_range().start
    }

    fn end(&self, node: &impl syn::spanned::Spanned) -> usize {
        self.base + node.span().byte_range().end
    }

    /// Every name `pattern` binds, scoped `[from, to)`.
    fn bind(&mut self, pattern: &syn::Pat, from: usize, to: usize) {
        struct Names(Vec<String>);
        impl<'ast> syn::visit::Visit<'ast> for Names {
            fn visit_pat_ident(&mut self, node: &'ast syn::PatIdent) {
                self.0.push(node.ident.to_string());
                syn::visit::visit_pat_ident(self, node);
            }
        }
        let mut names = Names(Vec::new());
        syn::visit::Visit::visit_pat(&mut names, pattern);
        self.scopes
            .extend(names.0.into_iter().map(|name| (name, from, to)));
    }

    /// The `let` patterns of a condition — one, or each of a `&&` chain — through `to`.
    fn bind_condition(&mut self, condition: &syn::Expr, to: usize) {
        match condition {
            syn::Expr::Let(binding) => {
                let from = self.end(binding);
                self.bind(&binding.pat, from, to);
            }
            syn::Expr::Binary(chain) if matches!(chain.op, syn::BinOp::And(_)) => {
                self.bind_condition(&chain.left, to);
                self.bind_condition(&chain.right, to);
            }
            syn::Expr::Paren(inner) => self.bind_condition(&inner.expr, to),
            _ => {}
        }
    }
}

impl<'ast> syn::visit::Visit<'ast> for ScopeReader {
    fn visit_block(&mut self, block: &'ast syn::Block) {
        let to = self.end(block);
        for statement in &block.stmts {
            if let syn::Stmt::Local(local) = statement {
                let from = self.end(local);
                self.bind(&local.pat, from, to);
            }
        }
        syn::visit::visit_block(self, block);
    }

    fn visit_expr_if(&mut self, node: &'ast syn::ExprIf) {
        self.bind_condition(&node.cond, self.end(&node.then_branch));
        syn::visit::visit_expr_if(self, node);
    }

    fn visit_expr_while(&mut self, node: &'ast syn::ExprWhile) {
        self.bind_condition(&node.cond, self.end(&node.body));
        syn::visit::visit_expr_while(self, node);
    }

    fn visit_expr_for_loop(&mut self, node: &'ast syn::ExprForLoop) {
        let (from, to) = (self.start(&node.body), self.end(&node.body));
        self.bind(&node.pat, from, to);
        syn::visit::visit_expr_for_loop(self, node);
    }

    fn visit_arm(&mut self, node: &'ast syn::Arm) {
        let (from, to) = (self.start(&node.pat), self.end(&node.body));
        self.bind(&node.pat, from, to);
        if let Some((_, guard)) = &node.guard {
            self.bind_condition(guard, to);
        }
        syn::visit::visit_arm(self, node);
    }

    fn visit_expr_closure(&mut self, node: &'ast syn::ExprClosure) {
        let (from, to) = (self.start(&node.body), self.end(&node.body));
        for input in &node.inputs {
            self.bind(input, from, to);
        }
        syn::visit::visit_expr_closure(self, node);
    }
}

/// **Whether a binding of `name` other than the parameter is in scope at the call whose name
/// token starts at union offset `call`** — the parameter's declared type then says nothing of
/// the receiver. Read from `syn`'s scopes ([`binding_scopes`]): a binding shadows only where its
/// scope holds the call, so one in a sibling or an already-closed block, or one that begins after
/// the call, does not. A body that does not parse gives no scope information, and the call is
/// read as shadowed (untyped).
fn shadowed_at(scopes: Option<&[BindingScope]>, name: &str, call: usize) -> bool {
    scopes.is_none_or(|scopes| {
        scopes
            .iter()
            .any(|(bound, from, to)| bound == name && *from <= call && call < *to)
    })
}
fn assigned(src: &Src, toks: &[Tok], name: &str, after: usize) -> bool {
    toks.iter().enumerate().any(|(at, tok)| {
        if tok.start <= after || !src.is(Some(tok), "=") {
            return false;
        }
        let start = toks[..at]
            .iter()
            .rposition(|candidate| {
                [";", "{", "}"]
                    .iter()
                    .any(|stop| src.is(Some(candidate), stop))
            })
            .map_or(0, |start| start + 1);
        let target = &toks[start..at];
        !target
            .iter()
            .any(|candidate| src.is(Some(candidate), "let"))
            && target
                .iter()
                .any(|candidate| candidate.kind == Kind::Ident && src.text(*candidate) == name)
    })
}

/// Locals whose receiver type is stated by exactly `let name: Type = …`, where the written type
/// is a reference or one unambiguous first-party path, the name has exactly one binding in the
/// whole function, and it is never assigned. Initializers never contribute a type.
fn local_types(
    world: &World,
    src: usize,
    annotated: &HashMap<&'static str, (usize, Vec<Tok>)>,
) -> HashMap<&'static str, (usize, BTreeSet<String>)> {
    let s = &world.srcs[src];
    annotated
        .iter()
        .filter_map(|(name, (bound, written))| {
            let types = world.written_type(src, s, written);
            (!types.is_empty()).then_some((*name, (*bound, types)))
        })
        .collect()
}

/// Locals bound by exactly `let name: Type = …`, the name having exactly one binding in the whole
/// function and never assigned: each with the offset its binding ends at and the written type's
/// tokens.
fn annotated_lets(
    s: &Src,
    toks: &[Tok],
    params: &HashMap<&str, Vec<Tok>>,
) -> HashMap<&'static str, (usize, Vec<Tok>)> {
    let mut found = HashMap::new();
    for (at, tok) in toks.iter().enumerate() {
        if !s.is(Some(tok), "let") {
            continue;
        }
        let end = let_end(s, toks, at + 1);
        let statement = &toks[at + 1..end];
        let Some(equal) = top_level_token(s, statement, "=") else {
            continue;
        };
        let pattern = &statement[..equal];
        let Some(colon) = top_level_token(s, pattern, ":") else {
            continue;
        };
        let binding: Vec<&Tok> = pattern[..colon]
            .iter()
            .filter(|tok| !s.is(Some(tok), "mut"))
            .collect();
        let [name] = binding.as_slice() else {
            continue;
        };
        if name.kind != Kind::Ident {
            continue;
        }
        let name = s.text(**name);
        let bound = toks.get(end).map_or(tok.end, |end| end.start);
        if binding_count(s, toks, params, name) == 1 && !assigned(s, toks, name, bound) {
            found.insert(name, (bound, pattern[colon + 1..].to_vec()));
        }
    }
    found
}

fn methods_of(all: &[Callable], types: &BTreeSet<String>) -> Vec<Callable> {
    all.iter()
        .filter(|c| c.type_owner.as_ref().is_some_and(|t| types.contains(t)))
        .cloned()
        .collect()
}

/// The calls and macro invocations in a run of tokens, in order.
fn sites_of(s: &Src, toks: &[Tok]) -> Vec<Site> {
    let mut out = Vec::new();
    for (at, tok) in toks.iter().enumerate() {
        if tok.kind != Kind::Ident {
            continue;
        }
        let name = s.text(*tok);
        // Past a turbofish: `name::<…>(`.
        let mut next = at + 1;
        if s.is(toks.get(next), "::") && s.is(toks.get(next + 1), "<") {
            let mut depth = 0usize;
            for (inner, t) in toks.iter().enumerate().skip(next + 1) {
                if t.kind != Kind::Punct {
                    continue;
                }
                match s.text(*t) {
                    "<" => depth += 1,
                    ">" => {
                        depth -= 1;
                        if depth == 0 {
                            next = inner + 1;
                            break;
                        }
                    }
                    _ => {}
                }
            }
        }
        if s.is(toks.get(next), "!")
            && ["(", "[", "{"]
                .iter()
                .any(|open| s.is(toks.get(next + 1), open))
        {
            out.push(Site {
                at: tok.start,
                name,
                form: Form::Macro,
            });
            continue;
        }
        if !s.is(toks.get(next), "(") || KEYWORDS.contains(&name) {
            continue;
        }
        let previous = at.checked_sub(1).map(|p| toks[p]);
        let form = if s.is(previous.as_ref(), ".") {
            Form::Method(receiver(s, toks, at - 1))
        } else if s.is(previous.as_ref(), "::") {
            let mut quals = Vec::new();
            let mut colons = at - 1;
            while s.is(toks.get(colons), "::") {
                match colons.checked_sub(1).map(|p| (p, toks[p])) {
                    Some((before, named)) if named.kind == Kind::Ident => {
                        quals.push(s.text(named));
                        let Some(further) = before.checked_sub(1) else {
                            break;
                        };
                        colons = further;
                    }
                    _ => {
                        quals.push("<qualified>");
                        break;
                    }
                }
            }
            quals.reverse();
            Form::Path(quals)
        } else if s.is(previous.as_ref(), "fn") {
            continue;
        } else {
            Form::Bare
        };
        out.push(Site {
            at: tok.start,
            name,
            form,
        });
        // The admission's work, handed over by value: `admitted::<…>(flush)`.
        if name == "admitted"
            && toks.get(next + 1).is_some_and(|t| t.kind == Kind::Ident)
            && s.is(toks.get(next + 2), ")")
        {
            out.push(Site {
                at: toks[next + 1].start,
                name: s.text(toks[next + 1]),
                form: Form::Value,
            });
        }
    }
    out
}

/// The receiver of the method call whose dot is `toks[dot]`, read backwards as `a.b.c`, when it
/// is a plain chain of names.
fn receiver(s: &Src, toks: &[Tok], dot: usize) -> Option<Vec<&'static str>> {
    let mut chain = Vec::new();
    let mut dot = dot;
    loop {
        let named = toks[dot.checked_sub(1)?];
        if named.kind != Kind::Ident {
            return None;
        }
        chain.push(s.text(named));
        match (dot - 1).checked_sub(1).map(|p| toks[p]) {
            Some(before) if s.is(Some(&before), ".") => dot -= 2,
            Some(before) if [")", "]", "?", "::"].iter().any(|p| s.is(Some(&before), p)) => {
                return None;
            }
            _ => break,
        }
    }
    chain.reverse();
    Some(chain)
}

// ── the vocabulary, as a call site shows it ─────────────────────────────────────────────────

/// One registry vocabulary line: its path's last two segments, and whether it waits.
struct Word {
    parent: String,
    last: String,
    waits: bool,
}

fn vocabulary() -> Vec<Word> {
    section("vocabulary", &VOCABULARY_COLUMNS)
        .into_iter()
        .map(|cells| {
            let mut segments: Vec<&str> = cells[0].split("::").collect();
            let last = segments.pop().unwrap_or_default().to_owned();
            let parent = segments.pop().unwrap_or_default().to_owned();
            Word {
                parent,
                last,
                waits: cells[2] != "counted by call site, does not wait",
            }
        })
        .collect()
}

/// The vocabulary effect a site is, named `Parent::last` — or a system call's own name — and
/// whether it waits. A method call matches a line whose parent is a type; a path matches by its
/// last qualifier; a bare call matches only a system call's capitalised name; `write!` and
/// `writeln!` are `Write::write_fmt`.
fn effect_of(words: &[Word], site: &Site) -> Option<(String, bool)> {
    let typed = |word: &&Word| word.parent.starts_with(|c: char| c.is_ascii_uppercase());
    let named = |word: &Word| (format!("{}::{}", word.parent, word.last), word.waits);
    match &site.form {
        Form::Macro if ["write", "writeln"].contains(&site.name) => {
            Some(("Write::write_fmt".to_owned(), true))
        }
        Form::Macro | Form::Value => None,
        Form::Method(_) => words
            .iter()
            .filter(typed)
            .find(|word| word.last == site.name)
            .map(named),
        Form::Path(quals) => {
            let qualifier = quals.last().copied().unwrap_or_default();
            words
                .iter()
                .find(|word| word.last == site.name && word.parent == qualifier)
                .map(named)
        }
        Form::Bare => words
            .iter()
            .find(|word| {
                word.last == site.name && site.name.starts_with(|c: char| c.is_ascii_uppercase())
            })
            .map(|word| (word.last.clone(), word.waits)),
    }
}

// ── assertion 0: the declared universe ──────────────────────────────────────────────────────

/// **Every first-party package outside `vendor/` is the product or a declared tool.** The
/// universe is `bt-app` and what it depends on; a new package nothing depends on and nobody
/// declared is a package this guard would silently not read.
fn the_universe_is_the_product_and_its_tools_are_declared(world: &World) -> Vec<String> {
    let workspace = bt_source::Workspace::read(&repository_root()).expect("the workspace");
    let mut failures = Vec::new();
    for package in workspace.packages() {
        let name = package.name();
        let product = world.srcs.iter().any(|src| src.package == name);
        if !bt_source::is_vendored(package.directory())
            && !product
            && !NOT_THE_PRODUCT.contains(&name)
        {
            failures.push(format!(
                "`{name}` is a first-party package that `folio.exe` does not depend on and \
                 `NOT_THE_PRODUCT` does not declare"
            ));
        }
        if product && NOT_THE_PRODUCT.contains(&name) {
            failures.push(format!(
                "`{name}` is declared a tool, and `bt-app` depends on it"
            ));
        }
    }
    failures
}

// ── assertion 1: the unsafe fences (§C-5, M14) ──────────────────────────────────────────────

/// The names no `unsafe` stretch and no fabrication expression may spell.
const CAPABILITY_NAMES: [&str; 4] = ["WaitToken", "WorkerCtx", "Leg", "doors"];
/// The expressions that make a value out of bytes: each spelling of the note's four.
const FABRICATION: [&str; 7] = [
    "transmute",
    "transmute_copy",
    "zeroed",
    "MaybeUninit",
    "read",
    "read_unaligned",
    "read_volatile",
];

/// Where an `unsafe` written at `at` reaches: its block, or the item it marks.
fn unsafe_region(src: &Src, at: usize) -> Option<(usize, usize)> {
    let end = src.file_end(at);
    let mut window = 512;
    loop {
        let toks = src.lex(at, (at + window).min(end));
        let next = toks.get(1)?;
        if src.is(Some(next), "{") {
            return Some((at, src.group(next.start).last()?.end));
        }
        if !["fn", "impl", "trait", "extern"]
            .iter()
            .any(|word| src.is(Some(next), word))
        {
            return None;
        }
        let mut depth = 0usize;
        for tok in toks.iter().skip(1).filter(|t| t.kind == Kind::Punct) {
            match src.text(*tok) {
                "(" | "[" => depth += 1,
                ")" | "]" => depth = depth.saturating_sub(1),
                "{" if depth == 0 => return Some((at, src.group(tok.start).last()?.end)),
                ";" if depth == 0 => return Some((at, tok.end)),
                _ => {}
            }
        }
        if at + window >= end {
            return None;
        }
        window *= 4;
    }
}

/// How far a fabrication expression written at `at` reaches: through its call's parentheses, or
/// to the end of the type it is written in.
fn fabrication_region(src: &Src, at: usize) -> (usize, usize) {
    let toks = src.lex(at, (at + 512).min(src.file_end(at)));
    let mut angle = 0usize;
    for tok in toks.iter().skip(1).filter(|t| t.kind == Kind::Punct) {
        match src.text(*tok) {
            "<" => angle += 1,
            ">" => angle = angle.saturating_sub(1),
            "(" if angle == 0 => {
                return (at, src.group(tok.start).last().map_or(tok.end, |t| t.end));
            }
            ";" | "{" | "}" | "," | "=" | ")" | "]" if angle == 0 => return (at, tok.start),
            _ => {}
        }
    }
    (at, toks.last().map_or(at, |t| t.end))
}

/// **No capability is named where the compiler checks nothing**: `WaitToken`, `WorkerCtx`, `Leg`
/// (which holds a token and lends it through `Leg::arm`) and `admission::doors` never inside an
/// `unsafe` block, `unsafe fn`, `unsafe impl` or `unsafe extern`, nor inside a `transmute`, `zeroed`, `MaybeUninit` or `read` expression, anywhere in
/// the product; and `admission` keeps `#![forbid(unsafe_code)]` and writes no `unsafe` — both of
/// its halves: `bt-effects`' module, which builds the capabilities, and `bt-platform`'s, the thread
/// door that lends the worker's.
///
/// What stays outside, as revision (b)2 names it: an inference-typed `transmute` inside
/// `bt-platform`'s own `unsafe`, whose type is fixed at the door's parameter rather than written.
fn no_capability_is_named_where_the_compiler_checks_nothing(world: &World) -> Vec<String> {
    let mut failures = Vec::new();
    let mut regions = 0;
    for src in &world.srcs {
        for at in src.named("unsafe") {
            let Some((from, to)) = unsafe_region(src, at) else {
                continue;
            };
            regions += 1;
            for (name_at, name) in src.names_in(from, to, &CAPABILITY_NAMES) {
                if src.in_product(name_at) {
                    failures.push(format!(
                        "`{name}` is named inside an `unsafe` stretch at {} ({})",
                        src.location(name_at),
                        src.owner_of(name_at)
                    ));
                }
            }
        }
        for word in FABRICATION {
            for at in src.named(word) {
                let (from, to) = fabrication_region(src, at);
                for (name_at, name) in src.names_in(from, to, &CAPABILITY_NAMES) {
                    if src.in_product(name_at) {
                        failures.push(format!(
                            "`{name}` is named inside a `{word}` expression at {} ({})",
                            src.location(name_at),
                            src.owner_of(name_at)
                        ));
                    }
                }
            }
        }
    }
    if regions == 0 {
        failures.push("no `unsafe` stretch was found in the product: this reads nothing".into());
    }
    for package in ["bt-effects", "bt-platform"] {
        let src = world.src(package);
        let Some(admission) = admission_module(src) else {
            failures.push(format!("{package} has no module `crate::admission`"));
            continue;
        };
        let forbids = attributes(src).into_iter().any(|attribute| {
            attribute.inner
                && admission.holds(attribute.start)
                && path_of(src, &attribute.body).0 == "forbid"
                && attribute.body.iter().any(|t| src.text(*t) == "unsafe_code")
        });
        if !forbids {
            failures.push(format!(
                "{package}'s `crate::admission` does not say `#![forbid(unsafe_code)]`: the module \
                 that builds or lends the capabilities is one the compiler must keep free of \
                 `unsafe` (§2.4)"
            ));
        }
        for at in src.named("unsafe") {
            if admission.holds(at) {
                failures.push(format!(
                    "`unsafe` is written in {package}'s `crate::admission` at {}",
                    src.location(at)
                ));
            }
        }
    }
    failures
}

/// The span of a package's module `crate::admission`.
fn admission_module(src: &Src) -> Option<bt_source::Span> {
    src.index
        .modules()
        .iter()
        .find(|module| {
            module
                .module_paths()
                .iter()
                .any(|p| p == "crate::admission")
        })
        .map(bt_source::ModuleRecord::span)
}

// ── assertion 2: one constructor (§2.4) ─────────────────────────────────────────────────────

/// Tokens that, written before `Name {`, make it a declaration or a type rather than a literal.
const NOT_A_LITERAL: [&str; 9] = [
    "struct", "enum", "union", "impl", "for", "trait", "->", "type", "dyn",
];

/// Every struct literal of `name` in a package's product code: `Name {`, and `Self {` inside the
/// type's own `impl` blocks — every spelling (Codex P8).
fn literals_of(src: &Src, name: &str) -> Vec<usize> {
    let is_literal = |at: usize| {
        let after = src.lex(at, (at + 64).min(src.file_end(at)));
        let file_start = src.index.file_at(at).map_or(0, |f| f.span().start());
        let before = src.lex(at.saturating_sub(64).max(file_start), at);
        src.is(after.get(1), "{")
            && !before
                .last()
                .is_some_and(|t| NOT_A_LITERAL.contains(&src.text(*t)))
    };
    let blocks: Vec<_> = src
        .index
        .impls()
        .iter()
        .filter(|block| block.type_owner() == name)
        .map(bt_source::ImplRecord::body)
        .collect();
    src.named(name)
        .into_iter()
        .chain(
            src.named("Self")
                .into_iter()
                .filter(|at| blocks.iter().any(|body| body.holds(*at))),
        )
        .filter(|at| is_literal(*at) && src.in_product(*at))
        .collect()
}

/// **A worker's capability has one constructor and no trait road to another**: one `WorkerCtx`
/// struct literal in the product, in `admission::lend_worker` (A1b), called by the thread door
/// and by `enter_standalone_main` once each; `WorkerCtx` and `WaitToken` each have one `impl`
/// block, the inherent one, and derive nothing.
///
/// **And the two mints are fenced** (A2a, revision (j)11.1), because an entrance that takes a
/// capability may leave the vocabulary only while nothing else can make one: `WaitToken`'s one
/// struct literal is `WaitToken::fresh`'s, and `fresh` is named in the product exactly where
/// `admission::admitted` calls it (twice: the unmetered and the metered road); `lend_worker` is
/// named exactly by its two owners. Every **reference** is counted — a name handed on as a
/// function value (`.map(WaitToken::fresh)`, `run(lend_worker)`) is one — by the identifier view,
/// never by the spelling `name(`. `fresh` and every field of both capabilities are private: that
/// pinned visibility is what keeps every reference to them inside `bt-effects`' `crate::admission`,
/// where this counts them. `lend_worker` is the one public mint, for the thread door, which is
/// `bt-platform`'s because it sets the platform's scheduling band (CC-3): its references are counted
/// in every package of the product, so a third caller anywhere is a failure here.
///
/// What stays outside, as revision (b)2 names it and (j)11.1 restates: an inference-typed
/// fabrication inside `bt-platform`'s own `unsafe` (a `transmute` whose target type is fixed at a
/// door's parameter rather than written) is not an accident this guard is built to catch.
fn a_capability_has_one_constructor_and_no_trait_road(world: &World) -> Vec<String> {
    let mut failures = Vec::new();
    let literals: Vec<String> = world
        .srcs
        .iter()
        .flat_map(|src| {
            literals_of(src, "WorkerCtx")
                .into_iter()
                .map(|at| src.owner_of(at))
        })
        .collect();
    if literals != ["bt-effects crate::admission::lend_worker"] {
        failures.push(format!(
            "`WorkerCtx` is built by a struct literal in one place, `admission::lend_worker`; \
             found {literals:?}"
        ));
    }
    let token_literals: Vec<String> = world
        .srcs
        .iter()
        .flat_map(|src| {
            literals_of(src, "WaitToken")
                .into_iter()
                .map(|at| src.owner_of(at))
        })
        .collect();
    if token_literals != ["bt-effects crate::admission::WaitToken::fresh"] {
        failures.push(format!(
            "`WaitToken` is built by a struct literal in one place, `WaitToken::fresh`; found \
             {token_literals:?}"
        ));
    }
    let admission = admission_module(world.src("bt-effects"));
    // Every reference in the product, its declaration excluded: a call, a value, a path to it.
    let references = |name: &str, within: Option<bt_source::Span>| {
        let mut found = BTreeMap::new();
        for src in &world.srcs {
            for at in src.named(name) {
                let file_start = src.index.file_at(at).map_or(0, |f| f.span().start());
                let before = src.lex(at.saturating_sub(8).max(file_start), at);
                let outside =
                    within.is_some_and(|span| src.package != "bt-effects" || !span.holds(at));
                if src.is(before.last(), "fn") || outside || !src.in_product(at) {
                    continue;
                }
                *found.entry(src.owner_of(at)).or_insert(0) += 1;
            }
        }
        found
    };
    let fresh = references("fresh", admission);
    let wanted_fresh = BTreeMap::from([("bt-effects crate::admission::admitted".to_owned(), 2)]);
    if fresh != wanted_fresh {
        failures.push(format!(
            "`WaitToken::fresh` is named only by `admission::admitted`, twice — a call or a value \
             is a reference, and any other is a second mint that skips the role, the phase and \
             the meter; found {fresh:?}"
        ));
    }
    let callers = references("lend_worker", None);
    let wanted = BTreeMap::from([
        (
            "bt-effects crate::admission::enter_standalone_main".to_owned(),
            1,
        ),
        (
            "bt-platform crate::admission::spawn_at_priority_with_stack".to_owned(),
            1,
        ),
    ]);
    if callers != wanted {
        failures.push(format!(
            "`lend_worker` is named by the thread door and by `enter_standalone_main`, once \
             each (a call or a value is a reference); found {callers:?}"
        ));
    }
    let effects = world.src("bt-effects");
    for (query, what) in [
        (
            ItemQuery::method("WaitToken", "fresh"),
            "`WaitToken::fresh`",
        ),
        (
            ItemQuery::field("WaitToken", "_scope"),
            "`WaitToken`'s `_scope`",
        ),
        (
            ItemQuery::field("WaitToken", "_door"),
            "`WaitToken`'s `_door`",
        ),
        (
            ItemQuery::field("WaitToken", "_local"),
            "`WaitToken`'s `_local`",
        ),
        (
            ItemQuery::field("WorkerCtx", "name"),
            "`WorkerCtx`'s `name`",
        ),
        (
            ItemQuery::field("WorkerCtx", "_local"),
            "`WorkerCtx`'s `_local`",
        ),
    ] {
        match effects.index.find(&query.in_module("crate::admission")) {
            Ok(records) => {
                for record in records {
                    let declaration =
                        effects.lex(record.declaration().start(), record.declaration().end());
                    if declaration.iter().any(|t| effects.text(*t) == "pub") {
                        failures.push(format!(
                            "{what} is visible outside `crate::admission` at {}: a mint, and a \
                             field a literal elsewhere could fill, stay private",
                            effects.location(record.whole().start())
                        ));
                    }
                }
            }
            Err(failure) => failures.push(format!("{what}: {failure}")),
        }
    }
    for type_name in ["WorkerCtx", "WaitToken"] {
        let blocks: Vec<String> = world
            .srcs
            .iter()
            .flat_map(|src| {
                src.index
                    .impls()
                    .iter()
                    .filter(|block| {
                        block.type_owner() == type_name && src.in_product(block.whole().start())
                    })
                    .map(|block| match block.trait_name() {
                        Some(name) => format!("impl {name} for {type_name}"),
                        None => format!("impl {type_name}"),
                    })
            })
            .collect();
        if blocks != [format!("impl {type_name}")] {
            failures.push(format!(
                "`{type_name}` has one `impl` block, its inherent one — no `Default`, `Clone`, \
                 `Copy`, `From`, `Send` or `Sync` road to another; found {blocks:?}"
            ));
        }
        match effects
            .index
            .find(&ItemQuery::type_item(type_name).in_module("crate::admission"))
        {
            Ok(records) => {
                for record in records {
                    let declaration =
                        effects.lex(record.declaration().start(), record.declaration().end());
                    if declaration.iter().any(|t| effects.text(*t) == "derive") {
                        failures.push(format!(
                            "`{type_name}` derives a trait at {}: a derived `Clone`, `Copy` or \
                             `Default` is a second constructor",
                            effects.location(record.whole().start())
                        ));
                    }
                }
            }
            Err(failure) => failures.push(format!("`crate::admission::{type_name}`: {failure}")),
        }
    }
    failures
}

// ── assertion 3: the pinned writers (§3.2, §4.2, (c)5, (c)6, (c)7) ──────────────────────────

/// One pinned call of a role or phase writer: who makes it, and the landmark it follows.
struct Pin {
    writer: &'static str,
    owner: &'static str,
    after: Option<&'static str>,
}

/// **One landmark of an owner's body, by the written shape it is read as**
/// (T-LANDMARK-GUARD-BY-CALL). A landmark is a call, or a variant's path — never a bare identifier:
/// a field, a binding or a parameter that happens to spell a landmark's name is not one.
#[derive(Clone, Copy)]
enum Landmark {
    /// The call of the crate's item at this path from the crate root, the last segment the
    /// landmark's name: read by what a written path resolves to, however it is spelled.
    Call(&'static [&'static str]),
    /// The method call `receiver.name(…)`, its receiver written as these segments joined by `.`.
    Method(&'static [&'static str], &'static str),
    /// The variant path `…::Enum::Variant` of one variant: the landmark `Variant`.
    Variant(&'static str, &'static str),
    /// Every variant path `…::Enum::V` of the enum, each the landmark `V`.
    Variants(&'static str),
}

impl Landmark {
    /// The identifier the landmark's own token spells: the call's last segment, the method, the
    /// variant, or — for every variant — the enum.
    fn name(self) -> &'static str {
        match self {
            Self::Call(path) => path[path.len() - 1],
            Self::Method(_, name) | Self::Variant(_, name) | Self::Variants(name) => name,
        }
    }
}

/// Each owner's landmarks. A pinned call's position is the nearest of them written before it in
/// the owner's body ([`landmarks_in`] reads them); for `QuitStep`'s variants, the arm it is in.
const LANDMARKS: [(&str, &[Landmark]); 4] = [
    (
        "bt-app crate::main",
        &[
            Landmark::Call(&["cli", "parse"]),
            Landmark::Call(&["launch_wire", "hand_over"]),
            Landmark::Method(&["builder"], "build"),
            Landmark::Method(&["event_loop"], "run_app"),
        ],
    ),
    (
        "bt-app crate::FolioApp::new_events",
        &[Landmark::Variant("StartCause", "Init")],
    ),
    (
        "bt-app crate::App::finish",
        &[Landmark::Method(&["self", "session_store"], "close")],
    ),
    (
        "bt-app crate::FolioApp::settle_quit",
        &[Landmark::Variants("QuitStep")],
    ),
];

